{"command":"python3 << 'PY'
import subprocess
def switch(gen,label):
 prev=None
 for n in range(0,50):
  inp=gen(n); p=subprocess.run(["./executable",":memory:"],input=inp,text=True,capture_output=True); ls=p.stderr.splitlines()
  if len(ls)<2: continue
  left="---^" in ls[1]; col=ls[1].find("^")-8
  if prev and left!=prev[1]: print(label,"switch",prev,"->",(col,left),"linelen",len(inp)-1); return
  prev=(col,left)
 print(label,"no",prev)
for tok in ["x","xx","xyz","x"*10,"x"*20,"x"*50]:
 switch(lambda n,tok=tok: ".mode "+" "*n+tok+"\n",tok)
for suffix in [""," abc"," aaaaaaaaaaaaaaaaaaaa"]:
 switch(lambda n,suffix=suffix: ".mode "+" "*n+"xyz"+suffix+"\n", "xyz"+suffix)
for pre in [".mode ",".mode list ",".mode list list list "]:
 switch(lambda n,pre=pre: pre+" "*n+"xyz\n",pre)
PY"}

