/*
** An independent reimplementation of an SQLite command-line shell,
** written from observations of the program's external behaviour.
** It uses the system SQLite library for the SQL database engine and
** implements the interactive/batch shell, output formatting and
** dot-commands itself.
*/
#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <strings.h>
#include <ctype.h>
#include <stdarg.h>
#include <stddef.h>
#include <unistd.h>
#include <errno.h>
#include <math.h>
#include <limits.h>
#include <time.h>
#include <signal.h>
#include <fcntl.h>
#include <pwd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <sys/time.h>
#include <sys/resource.h>
#include <sys/ioctl.h>
#include <dirent.h>
#include <regex.h>
#include <zlib.h>
#include "sqlite3.h"
#ifdef HAVE_READLINE
# include <readline/readline.h>
# include <readline/history.h>
#endif
/* We unconditionally check for readline headers in compile.sh environment */
#if defined(__has_include)
# if __has_include(<readline/readline.h>)
#  define USE_READLINE 1
#  include <readline/readline.h>
#  include <readline/history.h>
# endif
#endif

#include "help_text.h"

#define SHELL_SQLITE_VERSION "3.54.0"
#define SHELL_SOURCE_DATE "2026-04-14 20:02:49"
#define SHELL_SOURCE_HASH "49b3bac482c831f503c7f90c35959e7ea731950e991baba86b2ab95987d2539b"
#define SHELL_SOURCE_ID SHELL_SOURCE_DATE " " SHELL_SOURCE_HASH

/* ---------------- dynamic string ---------------- */
typedef struct Str Str;
struct Str { char *s; size_t n; size_t cap; };
static void str_init(Str *p){ p->s=0; p->n=0; p->cap=0; }
static void str_free(Str *p){ free(p->s); p->s=0; p->n=p->cap=0; }
static void str_clear(Str *p){ p->n=0; if(p->s) p->s[0]=0; }
static void str_reserve(Str *p, size_t extra){
  if(p->n+extra+1>p->cap){
    size_t nc = p->cap? p->cap*2 : 64;
    while(nc < p->n+extra+1) nc *= 2;
    p->s = (char*)realloc(p->s, nc);
    if(!p->s){ fprintf(stderr,"out of memory\n"); exit(1); }
    p->cap = nc;
  }
}
static void str_append_n(Str *p, const char *z, size_t n){
  if(!z){ n=0; }
  str_reserve(p,n);
  if(n) memcpy(p->s+p->n,z,n);
  p->n += n;
  if(p->s) p->s[p->n]=0;
}
static void str_append(Str *p, const char *z){ if(z) str_append_n(p,z,strlen(z)); }
static void str_append_c(Str *p, char c){ str_append_n(p,&c,1); }
static void str_appendf(Str *p, const char *fmt, ...){
  va_list ap; char *buf=0;
  va_start(ap,fmt);
  if(vasprintf(&buf,fmt,ap)>=0 && buf){ str_append(p,buf); free(buf); }
  va_end(ap);
}
static char *str_detach(Str *p){ char *z=p->s; if(!z){ z=(char*)malloc(1); z[0]=0; } p->s=0;p->n=p->cap=0; return z; }
static char *xstrdup(const char *z){ char *r; if(!z) z=""; r=(char*)malloc(strlen(z)+1); strcpy(r,z); return r; }
static char *xstrndup(const char *z, size_t n){ char *r=(char*)malloc(n+1); memcpy(r,z,n); r[n]=0; return r; }
static void *xmalloc(size_t n){ void *p=malloc(n?n:1); if(!p){ fprintf(stderr,"out of memory\n"); exit(1);} return p; }
static void *xrealloc(void *p,size_t n){ void *q=realloc(p,n?n:1); if(!q){ fprintf(stderr,"out of memory\n"); exit(1);} return q; }

/* ---------------- output modes ---------------- */
enum ModeKind {
  MODE_Ascii, MODE_Box, MODE_C, MODE_Column, MODE_Count, MODE_Csv,
  MODE_Html, MODE_Insert, MODE_Jatom, MODE_Jobject, MODE_Json, MODE_Line,
  MODE_List, MODE_Markdown, MODE_Off, MODE_Psql, MODE_Qbox, MODE_Quote,
  MODE_Split, MODE_Table, MODE_Tabs, MODE_Tcl
};
enum QuoteKind { Q_Off=0, Q_Sql, Q_Relaxed, Q_Csv, Q_Html, Q_Tcl, Q_Json, Q_Hex };
enum BlobQuote { B_Auto=0, B_Text, B_Sql, B_Hex, B_Tcl, B_Json, B_Size };
enum TitleKind { T_Off=0, T_On, T_Sql, T_Csv, T_Html, T_Tcl, T_Json };
enum EscapeKind { ESC_Auto=0, ESC_Off, ESC_Ascii, ESC_Symbol };

typedef struct ModeSet ModeSet;
struct ModeSet {
  int kind;
  char *zAlign;
  int border;
  int blobQuote;
  char *zColSep;
  int escape;
  int lineLimit;
  int charLimit;
  int titleLimit;
  int multiInsert;
  char *zNull;
  int quote;
  char *zRowSep;
  int screenWidth;     /* 0=none, -1=auto, >0 */
  char *zTableName;
  int textJsonb;
  int title;           /* TitleKind */
  int *aWidth;
  int nWidth;
  int wordWrap;
  int wrap;
};
static const char *mode_kind_name(int kind){
  switch(kind){
    case MODE_Ascii: return "ascii";
    case MODE_Box: return "box";
    case MODE_C: return "c";
    case MODE_Column: return "column";
    case MODE_Count: return "count";
    case MODE_Csv: return "csv";
    case MODE_Html: return "html";
    case MODE_Insert: return "insert";
    case MODE_Jatom: return "jatom";
    case MODE_Jobject: return "jobject";
    case MODE_Json: return "json";
    case MODE_Line: return "line";
    case MODE_List: return "list";
    case MODE_Markdown: return "markdown";
    case MODE_Off: return "off";
    case MODE_Psql: return "psql";
    case MODE_Qbox: return "qbox";
    case MODE_Quote: return "quote";
    case MODE_Split: return "split";
    case MODE_Table: return "table";
    case MODE_Tabs: return "tabs";
    case MODE_Tcl: return "tcl";
  }
  return "list";
}
static int mode_titles_applicable(int kind){
  return !(kind==MODE_Count || kind==MODE_Json || kind==MODE_Jobject || kind==MODE_Line || kind==MODE_Off);
}
static void modeset_free(ModeSet *m){
  free(m->zAlign); free(m->zColSep); free(m->zNull); free(m->zRowSep); free(m->zTableName); free(m->aWidth);
  memset(m,0,sizeof(*m));
}
static void modeset_copy(ModeSet *dst, const ModeSet *src){
  modeset_free(dst);
  *dst = *src;
  dst->zAlign = xstrdup(src->zAlign?src->zAlign:"");
  dst->zColSep = xstrdup(src->zColSep?src->zColSep:"");
  dst->zNull = xstrdup(src->zNull?src->zNull:"");
  dst->zRowSep = xstrdup(src->zRowSep?src->zRowSep:"");
  dst->zTableName = xstrdup(src->zTableName?src->zTableName:"");
  dst->aWidth = 0;
  if(src->nWidth>0){ dst->aWidth=(int*)xmalloc(sizeof(int)*src->nWidth); memcpy(dst->aWidth,src->aWidth,sizeof(int)*src->nWidth); }
}
static void modeset_preset(ModeSet *m, int kind){
  modeset_free(m);
  memset(m,0,sizeof(*m));
  m->kind = kind;
  m->zAlign = xstrdup("");
  m->border = 1;
  m->blobQuote = B_Auto;
  m->zColSep = xstrdup("|");
  m->escape = ESC_Auto;
  m->zNull = xstrdup("");
  m->quote = Q_Off;
  m->zRowSep = xstrdup("\n");
  m->screenWidth = 0;
  m->zTableName = xstrdup("");
  m->title = T_Off;
  switch(kind){
    case MODE_Ascii:
      free(m->zColSep); m->zColSep = xstrdup("\037");
      free(m->zRowSep); m->zRowSep = xstrdup("\036");
      break;
    case MODE_Box: case MODE_Column: case MODE_Markdown: case MODE_Table:
      m->title = T_On; break;
    case MODE_C:
      m->blobQuote = B_Tcl; free(m->zColSep); m->zColSep=xstrdup(",");
      free(m->zNull); m->zNull=xstrdup("NULL"); m->quote=Q_Tcl; break;
    case MODE_Csv:
      free(m->zColSep); m->zColSep=xstrdup(","); m->quote=Q_Hex;
      free(m->zRowSep); m->zRowSep=xstrdup("\r\n"); break;
    case MODE_Html:
      m->quote = Q_Csv; m->title=T_On; break;
    case MODE_Insert:
      free(m->zNull); m->zNull=xstrdup("NULL"); m->quote=Q_Sql; break;
    case MODE_Jatom:
      free(m->zColSep); m->zColSep=xstrdup(","); free(m->zNull); m->zNull=xstrdup("null"); m->quote=Q_Json; break;
    case MODE_Jobject: case MODE_Json:
      free(m->zNull); m->zNull=xstrdup("null"); m->quote=Q_Json; break;
    case MODE_Line:
      free(m->zColSep); m->zColSep=xstrdup(": "); break;
    case MODE_Psql:
      m->border=0; m->title=T_On; break;
    case MODE_Qbox:
      free(m->zNull); m->zNull=xstrdup("NULL"); m->quote=Q_Sql; m->title=T_On; break;
    case MODE_Quote:
      free(m->zColSep); m->zColSep=xstrdup(","); free(m->zNull); m->zNull=xstrdup("NULL"); m->quote=Q_Sql; break;
    case MODE_Split:
