  else goLeft = col>markerLen;
  fputs(zPrefix,f);
  if(!goLeft){
    int i; for(i=0;i<col;i++) fputc(' ',f);
    fprintf(f,"^--- %s\n",zMsg);
  }else{
    int spaces=col-markerLen+1; int i; if(spaces<0) spaces=0;
