  if(ctx && ctx->zArgLabel){
    fprintf(stderr,"%s in %s: %s\n",zKind,ctx->zArgLabel,zMsg);
  }else if(ctx && ctx->zFile){
    fprintf(stderr,"%s near line %d of %s: %s\n",zKind,startLine,ctx->zFile,zMsg);
  }else{
    fprintf(stderr,"%s near line %d: %s\n",zKind,startLine,zMsg);
  }
  if(offset>=0 && zSql){
    /* flatten */
    Str flat; size_t i; int start=0; int dispLen; int caretInWin;
    str_init(&flat);
    for(i=0; zSql[i]; i++){
      unsigned char c=(unsigned char)zSql[i];
      if(c<0x20 || c==0x7f) str_append_c(&flat,' ');
      else str_append_c(&flat,(char)c);
    }
    while(flat.n && flat.s[flat.n-1]==' '){ flat.n--; flat.s[flat.n]=0; }
    if(offset>(int)flat.n) offset=(int)flat.n;
    dispLen=(int)flat.n;
    if(dispLen>78){
      start = offset<=50? 0 : offset-50;
      dispLen = 78;
      if(start+dispLen>(int)flat.n) dispLen=(int)flat.n-start;
    }
    fprintf(stderr,"  %.*s\n",dispLen,flat.s+start);
    caretInWin = offset-start;
    print_caret_line(stderr,"  ",caretInWin,"error here",1);
    str_free(&flat);
  }
  p->nErr++;
}
/* dot-command style error: line N: <line> / line N: <caret> msg [/ line N: extra] */
static void dot_error(Shell *p, const char *zLine, int lineNo, int col, const char *zMsg, const char *zExtra){
  char prefix[64];
  snprintf(prefix,sizeof(prefix),"line %d: ",lineNo>0?lineNo:(p->input?p->input->lineno:1));
