static char *relaxed_quote_text(Shell *p, const char *z){
  size_t n;
  if(!z) z="";
  n=strlen(z);
  if(text_has_control(z)) return sql_quote_text(p,z);
  if(n==0 || z[0]==' ' || z[n-1]==' ' || looks_like_relaxed_number(z) || looks_like_blob_literal(z)){
