    unsigned char c=*u;
    switch(c){
      case '"': str_append(&s,"\\\""); break;
      case '\\': str_append(&s,"\\\\"); break;
      case '\b': str_append(&s,"\\b"); break;
      case '\f': str_append(&s,"\\f"); break;
      case '\n': str_append(&s,"\\n"); break;
      case '\r': str_append(&s,"\\r"); break;
      case '\t': str_append(&s,"\\t"); break;
