}
static char *tcl_quote_text(const char *z){
  Str s; const unsigned char *u=(const unsigned char*)(z?z:"");
  str_init(&s); str_append_c(&s,'"');
  for(; *u; u++){
    unsigned char c=*u;
    switch(c){
