}
static char *render_blob(Shell *p, const void *blob, int n){
  ModeSet *m=&p->mode; int bq=m->blobQuote; Str s; int i;
  const unsigned char *b=(const unsigned char*)blob;
  if(!b) n=0;
  if(bq==B_Auto){
    if(m->quote==Q_Sql||m->quote==Q_Relaxed) bq=B_Sql;
    else if(m->quote==Q_Json) bq=B_Json;
    else if(m->quote==Q_Tcl) bq=B_Tcl;
    else bq=B_Text;
  }
  switch(bq){
    case B_Sql: {
      str_init(&s); str_append(&s,"x'");
