      str_append_c(&s,'"'); return str_detach(&s);
    }
    case B_Json: {
      str_init(&s); str_append_c(&s,'"');
      for(i=0;i<n;i++) str_appendf(&s,"\\u%04x",b[i]);
      str_append_c(&s,'"'); return str_detach(&s);
    }
    case B_Size: {
      char buf[64]; snprintf(buf,sizeof(buf),"(%d-byte blob)",n); return xstrdup(buf);
    }
    case B_Text: default: {
      char *z=blob_as_cstring(blob,n);
