          case Q_Sql: r=sql_quote_text(p,z); break;
          case Q_Relaxed: r=relaxed_quote_text(p,z); break;
          case Q_Json: r=json_quote_text(z); break;
          case Q_Tcl: r=tcl_quote_text(z); break;
          case Q_Csv: case Q_Hex: r=csv_quote_text(p,z,m->zColSep[0]); break;
          case Q_Html: r=html_escape_text(p,z); break;
          default: r=escape_transform(p,z,0); break;
        }
        free(z); return r;
      }
