static char *render_text_with_quote(Shell *p, const char *z, int quoteKind){
  if(!z) z="";
  switch(quoteKind){
    case Q_Sql: return sql_quote_text(p,z);
    case Q_Relaxed: return relaxed_quote_text(p,z);
    case Q_Json: return json_quote_text(z);
    case Q_Tcl: return tcl_quote_text(z);
    case Q_Html: return html_escape_text(p,z);
    case Q_Csv: return csv_quote_text(p,z,',');
    case Q_Hex: return csv_quote_text(p,z,p->mode.zColSep[0]);
    case Q_Off: default: return escape_transform(p,z,0);
  }
}
static char *render_title(Shell *p, const char *z){
  if(!z) z="";
  switch(p->mode.title){
    case T_Sql: return sql_quote_text(p,z);
    case T_Csv: return csv_quote_text(p,z,p->mode.zColSep[0]?p->mode.zColSep[0]:',');
    case T_Html: return html_escape_text(p,z);
    case T_Tcl: return tcl_quote_text(z);
    case T_Json: return json_quote_text(z);
    case T_On: default: {
      /* columnar/html modes render titles plain/escaped specially - callers for those avoid this path where needed */
      return render_text_with_quote(p,z,p->mode.quote);
    }
  }
}
static char *format_real(double v){
  char buf[128];
  sqlite3_snprintf(sizeof(buf),buf,"%!.17g",v);
  return xstrdup(buf);
}
/* Render a single column value according to mode.quote (generic modes).
** Returns malloc'd string. zText is the text representation for non-blob types. */
static char *render_value(Shell *p, int type, const char *zText, const void *blob, int nBlob){
  if(type==SQLITE_NULL) return xstrdup(p->mode.zNull);
  if(type==SQLITE_BLOB){
    char *r=render_blob(p,blob,nBlob);
    /* csv/tabs modes: blobs rendered as text need csv quoting when auto */
    if((p->mode.kind==MODE_Csv||p->mode.kind==MODE_Tabs) && p->mode.blobQuote==B_Auto){
      char *q=csv_quote_text(p,r,p->mode.zColSep[0]);
      /* csv_quote_text applied escape again - control chars already escaped, second pass is idempotent except ^ */
      free(r); return q;
    }
    return r;
  }
  if(type==SQLITE_INTEGER || type==SQLITE_FLOAT) return xstrdup(zText?zText:"");
  /* TEXT */
  return render_text_with_quote(p,zText,p->mode.quote);
}
