/* ---------------- row output ---------------- */
typedef struct RowSet RowSet;
struct RowSet {
  int nCol;
  char **azCol;      /* column names */
  int nRow;
  int capRow;
  char ***aaVal;     /* rendered values [row][col] */
  int **aaType;
  char ***aaRaw;     /* raw text (for json subtype etc) */
  int **aaSubtype;
};
static void rowset_free(RowSet *r){
  int i,j;
  if(r->azCol){ for(i=0;i<r->nCol;i++) free(r->azCol[i]); free(r->azCol); }
  for(i=0;i<r->nRow;i++){
    for(j=0;j<r->nCol;j++){ free(r->aaVal[i][j]); free(r->aaRaw[i][j]); }
    free(r->aaVal[i]); free(r->aaRaw[i]); free(r->aaType[i]); free(r->aaSubtype[i]);
  }
  free(r->aaVal); free(r->aaRaw); free(r->aaType); free(r->aaSubtype);
  memset(r,0,sizeof(*r));
}
static int effective_screenwidth(Shell *p){
  if(p->mode.screenWidth>0) return p->mode.screenWidth;
  if(p->mode.screenWidth<0){
    struct winsize ws;
    if(isatty(STDOUT_FILENO) && ioctl(STDOUT_FILENO,TIOCGWINSZ,&ws)==0 && ws.ws_col>0) return ws.ws_col;
    if(isatty(STDIN_FILENO) && ioctl(STDIN_FILENO,TIOCGWINSZ,&ws)==0 && ws.ws_col>0) return ws.ws_col;
    return 80;
  }
  return 0;
}
