      if(cp!='\n'){
        cnt++;
        if(cnt==limit) cut=i+len;
        if(cnt>limit) break;
      }
      i+=len;
    }
    if(cnt<=limit) return xstrdup(z);
    { Str s; str_init(&s); str_append_n(&s,z,cut); str_append(&s,"..."); return str_detach(&s); }
  }
}
