static char **cell_segments(const char *z, int width, int wordWrap, int lineLimit, int *pn){
  int nPhys=0; char **phys=split_physical_lines(z?z:"",&nPhys);
  char **az=0; int n=0,cap=0; int i;
  int limitLines=nPhys;
  if(lineLimit>0 && nPhys>lineLimit) limitLines=lineLimit;
  for(i=0;i<limitLines;i++) wrap_line_into(phys[i],width,wordWrap,&az,&n,&cap);
  if(lineLimit>0 && nPhys>lineLimit){
    if(n>=cap){ cap=cap?cap*2:8; az=(char**)xrealloc(az,sizeof(char*)*cap); }
    az[n++]=xstrdup("...");
  }
  free_str_array(phys,nPhys);
  *pn=n; return az;
}
static void append_padded(Str *s, const char *z, int width, int align){ /* align 0 left 1 center 2 right */
  int w=str_display_width(z); int left=0,right=0; int i;
  if(w<width){
    if(align==2) left=width-w;
    else if(align==1){ left=(width-w)/2; right=width-w-left; }
    else right=width-w;
  }
  for(i=0;i<left;i++) str_append_c(s,' ');
  str_append(s,z);
  for(i=0;i<right;i++) str_append_c(s,' ');
}
static void trim_trailing_spaces(Str *s){ while(s->n && s->s[s->n-1]==' '){ s->n--; s->s[s->n]=0; } }
static int column_align(Shell *p, int col, int type, int specifiedWidth){
  if(specifiedWidth<0) return 2;
  if(p->mode.zAlign && p->mode.zAlign[col]){
    char c=p->mode.zAlign[col];
    if(c=='C'||c=='c') return 1;
    if(c=='R'||c=='r') return 2;
    return 0;
  }
  if(type==SQLITE_INTEGER||type==SQLITE_FLOAT) return 2;
  return 0;
}
/* Sanitize raw control chars remaining in a rendered cell for columnar display */
static char *sanitize_columnar(Shell *p, const char *z){
  Str s; const unsigned char *u=(const unsigned char*)(z?z:"");
  (void)p; str_init(&s);
  for(; *u; u++){
    unsigned char c=*u;
    if(c<0x20 && c!='\n' && c!='\t') append_utf8(&s,0x2400+c);
    else str_append_c(&s,(char)c);
  }
  return str_detach(&s);
}
