static void output_split_values(Shell *p, char **azVal, int *aType, int n, int sw){
  int i;
  if(n<=0) return;
  if(sw<=0){
    for(i=0;i<n;i++){ out_write(p,azVal[i]); out_write(p,"\n"); }
    return;
  }
  {
    int bestK=1,bestR=n; int *bestWidths=0;
    int k;
    /* try all column counts; choose minimal rows, then smallest k */
    for(k=1;k<=n;k++){
      int R=(n+k-1)/k; int *w=(int*)xmalloc(sizeof(int)*k); int j; long sum=0; long total;
      for(j=0;j<k;j++){
        int m=0; int r;
        for(r=0;r<R;r++){ int idx=j*R+r; if(idx<n){ int wd=str_display_width(azVal[idx]); if(wd>m)m=wd; } }
        w[j]=m; sum+=m;
      }
      total=sum+(k>1?(k-1)*2:0);
      if(total<=sw || k==1){
        if(R<bestR || (R==bestR && k<bestK && bestWidths!=0) || bestWidths==0){
          /* only replace if strictly fewer rows, or first feasible */
          if(bestWidths==0 || R<bestR){
            free(bestWidths); bestWidths=w; bestK=k; bestR=R;
          }else free(w);
        }else free(w);
      }else free(w);
    }
    if(!bestWidths){ bestK=1; bestR=n; bestWidths=(int*)xmalloc(sizeof(int)); bestWidths[0]=0; for(i=0;i<n;i++){int wd=str_display_width(azVal[i]); if(wd>bestWidths[0])bestWidths[0]=wd;} }
    {
      int sep=5; int r,j; long sum=0;
      for(j=0;j<bestK;j++) sum+=bestWidths[j];
      if(bestK>1){ long avail=(long)sw-sum; long s=avail/(bestK-1); if(s<2)s=2; if(s>5)s=5; sep=(int)s; }
      for(r=0;r<bestR;r++){
        Str line; str_init(&line);
        for(j=0;j<bestK;j++){
          int idx=j*bestR+r;
          if(idx>=n) break;
          if(j>0){ int q; for(q=0;q<sep;q++) str_append_c(&line,' '); }
          append_padded(&line,azVal[idx],bestWidths[j],column_align(p,0,aType?aType[idx]:SQLITE_TEXT,0));
        }
        trim_trailing_spaces(&line);
        out_write_n(p,line.s?line.s:"",line.n); out_write(p,"\n");
        str_free(&line);
      }
    }
    free(bestWidths);
  }
}

