            for(j=0;j<rs->nCol;j++){ char *q=quote_identifier(rs->azCol[j]); if(j)str_append_c(&stmt,','); str_append(&stmt,q); free(q); }
            str_append_c(&stmt,')');
          }
          str_append(&stmt," VALUES"); str_append(&stmt,vals.s); have=1;
        }else{
          /* would-be addition length: ",\n  " + vals + ";" */
          if((int)(stmt.n + vals.n + 5) > p->mode.multiInsert){
            str_append_c(&stmt,';'); out_write_n(p,stmt.s,stmt.n); out_write(p,p->mode.zRowSep);
            str_clear(&stmt); str_appendf(&stmt,"INSERT INTO %s",zQTab);
            if(p->mode.title!=T_Off){
              str_append_c(&stmt,'(');
              for(j=0;j<rs->nCol;j++){ char *q=quote_identifier(rs->azCol[j]); if(j)str_append_c(&stmt,','); str_append(&stmt,q); free(q); }
              str_append_c(&stmt,')');
            }
            str_append(&stmt," VALUES"); str_append(&stmt,vals.s);
          }else{
            str_append(&stmt,",\n  "); str_append(&stmt,vals.s);
          }
        }
      }else{
        Str one; str_init(&one);
        str_appendf(&one,"INSERT INTO %s",zQTab);
        if(p->mode.title!=T_Off){
          str_append_c(&one,'(');
          for(j=0;j<rs->nCol;j++){ char *q=quote_identifier(rs->azCol[j]); if(j)str_append_c(&one,','); str_append(&one,q); free(q); }
          str_append_c(&one,')');
        }
        str_append(&one," VALUES"); str_append(&one,vals.s); str_append_c(&one,';');
        out_write_n(p,one.s,one.n); out_write(p,p->mode.zRowSep); str_free(&one);
      }
      str_free(&vals);
    }
    if(have){ str_append_c(&stmt,';'); out_write_n(p,stmt.s,stmt.n); out_write(p,p->mode.zRowSep); }
    str_free(&stmt); free(zQTab);
    return;
  }
  /* simple modes */
  if(p->mode.title!=T_Off){
    for(j=0;j<rs->nCol;j++){
      char *t=render_title(p,rs->azCol[j]);
      if(j>0) out_write(p,p->mode.zColSep);
      out_write(p,t); free(t);
    }
    out_write(p,p->mode.zRowSep);
  }
  for(i=0;i<rs->nRow;i++){
    for(j=0;j<rs->nCol;j++){
      if(j>0) out_write(p,p->mode.zColSep);
      if(kind==MODE_Jatom && rs->aaSubtype[i][j]==74) out_write(p,rs->aaRaw[i][j]);
      else out_write(p,rs->aaVal[i][j]);
    }
    out_write(p,p->mode.zRowSep);
  }
}
