{"command":"cat >> src/main.c << 'EOF'

/* ---------------- statement execution ---------------- */
static int process_input(Shell *p, InputCtx *ctx);
static int exec_sql(Shell *p, const char *zSql, InputCtx *ctx, int startLine);
static int handle_dot_command(Shell *p, const char *zLine, InputCtx *ctx);
static void print_stats(Shell *p, sqlite3_stmt *stmt, int stmtOnly);
static void open_db(Shell *p, const char *zName, int isDotOpen);
static void register_shell_functions(Shell *p, sqlite3 *db);
static void shell_trace_stmt(Shell *p, sqlite3_stmt *stmt, const char *zSql);

static const char *first_keyword(const char *z, char *buf, size_t bufsz){
  const char *s=z; size_t n=0;
  for(;;){
    while(s && isspace((unsigned char)*s)) s++;
    if(s && s[0]=='-'&&s[1]=='-'){ while(*s && *s!='\n') s++; continue; }
    if(s && s[0]=='/'&&s[1]=='*'){ const char *e=strstr(s+2,"*/"); if(!e){ s=""; break; } s=e+2; continue; }
    break;
  }
  if(!s) s="";
  while(s[n] && isalpha((unsigned char)s[n]) && n+1<bufsz){ buf[n]=s[n]; n++; }
  buf[n]=0;
  return s;
}
static int starts_explain(const char *z, int *isQP){
  char kw[32]; const char *s=first_keyword(z,kw,sizeof(kw)); char kw2[32]; const char *s2;
  if(isQP) *isQP=0;
  if(strcasecmp(kw,"EXPLAIN")!=0) return 0;
  s2=first_keyword(s+strlen(kw),kw2,sizeof(kw2));
  (void)s2;
  if(strcasecmp(kw2,"QUERY")==0){ if(isQP) *isQP=1; }
  return 1;
}
static void output_eqp_tree(Shell *p, RowSet *rs){
  int i;
  out_write(p,"QUERY PLAN\n");
  if(rs->nCol<4) return;
  /* Build recursively using id/parent */
  {
    int n=rs->nRow; int *ids=(int*)xmalloc(sizeof(int)*(n?n:1)); int *parents=(int*)xmalloc(sizeof(int)*(n?n:1));
    /* iterative stack for traversal */
    typedef struct Frame { int idx; char *prefix; int isLast; } Frame;
    /* Simpler: recursive via function-like loop using explicit stack of children enumeration */
    /* We do a recursive descent with a helper implemented as a stack of iterators */
    struct Iter { int parentId; int nextChildPos; char *prefix; int *children; int nChild; int childIdx; };
    struct Iter *stack=0; int sp=0, cap=0;
    #define PUSH_ITER(it) do{ if(sp>=cap){cap=cap?cap*2:16; stack=(struct Iter*)xrealloc(stack,sizeof(struct Iter)*cap);} stack[sp++]=(it);}while(0)
    for(i=0;i<n;i++){ ids[i]=atoi(rs->aaRaw[i][0]); parents[i]=atoi(rs->aaRaw[i][1]); }
    {
      struct Iter root; int j; root.parentId=0; root.prefix=xstrdup(""); root.children=(int*)xmalloc(sizeof(int)*(n?n:1)); root.nChild=0; root.childIdx=0; root.nextChildPos=0;
      for(j=0;j<n;j++) if(parents[j]==0) root.children[root.nChild++]=j;
      PUSH_ITER(root);
    }
    while(sp>0){
      struct Iter *it=&stack[sp-1];
      if(it->childIdx>=it->nChild){ free(it->prefix); free(it->children); sp--; continue; }
      { int idx=it->children[it->childIdx]; int isLast=(it->childIdx==it->nChild-1); char *savedPrefix=xstrdup(it->prefix);
        it->childIdx++;
        out_write(p,savedPrefix);
        out_write(p,isLast?"`--":"|--");
        out_write(p,rs->aaRaw[idx][3]); out_write(p,"\n");
        /* push children of idx */
        { struct Iter child; int j; Str pre; str_init(&pre); str_append(&pre,savedPrefix); str_append(&pre,isLast?"   ":"|  ");
          child.parentId=ids[idx]; child.prefix=str_detach(&pre); child.children=(int*)xmalloc(sizeof(int)*(n?n:1)); child.nChild=0; child.childIdx=0; child.nextChildPos=0;
          for(j=0;j<n;j++) if(parents[j]==ids[idx]) child.children[child.nChild++]=j;
          /* re-fetch stack pointer may move */
          PUSH_ITER(child);
        }
        free(savedPrefix);
      }
    }
    #undef PUSH_ITER
    free(stack); free(ids); free(parents);
  }
}
static void output_explain_bytecode(Shell *p, RowSet *rs){
  static const int minW[8]={4,13,4,4,4,13,2,13};
  int nCol=rs->nCol; int *w=(int*)xmalloc(sizeof(int)*(nCol?nCol:1)); int i,j;
  if(rs->nRow==0){ free(w); return; }
  for(j=0;j<nCol;j++){
    int mw=(j<8?minW[j]:4); int hw=str_display_width(rs->azCol[j]); if(hw>mw)mw=hw;
    for(i=0;i<rs->nRow;i++){ int cw=str_display_width(rs->aaRaw[i][j]); if(cw>mw)mw=cw; }
    w[j]=mw;
  }
  { Str line; str_init(&line); for(j=0;j<nCol;j++){ if(j)str_append(&line,"  "); append_padded(&line,rs->azCol[j],w[j],0);} str_append_c(&line,'\n'); out_write_n(p,line.s,line.n); str_free(&line); }
  { Str line; str_init(&line); for(j=0;j<nCol;j++){ int q; if(j)str_append(&line,"  "); for(q=0;q<w[j];q++)str_append_c(&line,'-');} str_append_c(&line,'\n'); out_write_n(p,line.s,line.n); str_free(&line); }
  for(i=0;i<rs->nRow;i++){
    Str line; str_init(&line); for(j=0;j<nCol;j++){ if(j)str_append(&line,"  "); append_padded(&line,rs->aaRaw[i][j],w[j],0);} trim_trailing_spaces(&line); str_append_c(&line,'\n'); out_write_n(p,line.s,line.n); str_free(&line);
  }
  free(w);
}
static void bind_parameters(Shell *p, sqlite3_stmt *stmt){
  int i,n=sqlite3_bind_parameter_count(stmt);
  for(i=1;i<=n;i++){
    const char *zName=sqlite3_bind_parameter_name(stmt,i);
    ParamBinding *b;
    for(b=p->params;b;b=b->next){
      if(zName && strcmp(b->zName,zName)==0){ sqlite3_bind_text(stmt,i,b->zValue,-1,SQLITE_TRANSIENT); break; }
      if(!zName){
        char buf[32]; snprintf(buf,sizeof(buf),"?%d",i);
        if(strcmp(b->zName,buf)==0 || strcmp(b->zName,"?")==0){ sqlite3_bind_text(stmt,i,b->zValue,-1,SQLITE_TRANSIENT); break; }
      }
    }
  }
}
/* Collect all rows from a prepared stmt. Returns sqlite rc from final step. *pzErr malloc'd on error. */
static int collect_stmt(Shell *p, sqlite3_stmt *stmt, RowSet *rs, int render, char **pzErr){
  int nCol=sqlite3_column_count(stmt); int rc; int j;
  if(pzErr) *pzErr=0;
  memset(rs,0,sizeof(*rs)); rs->nCol=nCol;
  rs->azCol=(char**)xmalloc(sizeof(char*)*(nCol?nCol:1));
  for(j=0;j<nCol;j++){ const char *n=sqlite3_column_name(stmt,j); rs->azCol[j]=xstrdup(n?n:""); }
  bind_parameters(p,stmt);
  shell_trace_stmt(p,stmt,0);
  while((rc=sqlite3_step(stmt))==SQLITE_ROW){
    char **azVal; char **azRaw; int *aType; int *aSub;
    if(rs->nRow>=rs->capRow){
      rs->capRow=rs->capRow?rs->capRow*2:64;
      rs->aaVal=(char***)xrealloc(rs->aaVal,sizeof(char**)*rs->capRow);
      rs->aaRaw=(char***)xrealloc(rs->aaRaw,sizeof(char**)*rs->capRow);
      rs->aaType=(int**)xrealloc(rs->aaType,sizeof(int*)*rs->capRow);
      rs->aaSubtype=(int**)xrealloc(rs->aaSubtype,sizeof(int*)*rs->capRow);
    }
    azVal=(char**)xmalloc(sizeof(char*)*(nCol?nCol:1));
    azRaw=(char**)xmalloc(sizeof(char*)*(nCol?nCol:1));
    aType=(int*)xmalloc(sizeof(int)*(nCol?nCol:1));
    aSub=(int*)xmalloc(sizeof(int)*(nCol?nCol:1));
    for(j=0;j<nCol;j++){
      int type=sqlite3_column_type(stmt,j); const char *zText=0; char numbuf[64];
      aType[j]=type;
      aSub[j]=(int)sqlite3_column_subtype(stmt,j);
      if(type==SQLITE_INTEGER){ snprintf(numbuf,sizeof(numbuf),"%lld",(long long)sqlite3_column_int64(stmt,j)); azRaw[j]=xstrdup(numbuf); zText=azRaw[j]; }
      else if(type==SQLITE_FLOAT){ azRaw[j]=format_real(sqlite3_column_double(stmt,j)); zText=azRaw[j]; }
      else if(type==SQLITE_BLOB){ const void *b=sqlite3_column_blob(stmt,j); int nb=sqlite3_column_bytes(stmt,j); azRaw[j]=blob_as_cstring(b,nb); zText=azRaw[j]; (void)zText; }
      else if(type==SQLITE_NULL){ azRaw[j]=xstrdup(""); }
      else { const unsigned char *t=sqlite3_column_text(stmt,j); azRaw[j]=xstrdup(t?(const char*)t:""); zText=azRaw[j]; }
      if(render){
        char *rv;
        if(type==SQLITE_BLOB){ const void *b=sqlite3_column_blob(stmt,j); int nb=sqlite3_column_bytes(stmt,j); rv=render_value(p,type,azRaw[j],b,nb); }
        else rv=render_value(p,type,azRaw[j],0,0);
        if(p->mode.charLimit>0 && p->mode.kind!=MODE_Json && p->mode.kind!=MODE_Jobject){
          char *tr=apply_charlimit(rv,p->mode.charLimit); free(rv); rv=tr;
        }
        azVal[j]=rv;
      }else{
        azVal[j]=xstrdup(azRaw[j]);
      }
    }
    rs->aaVal[rs->nRow]=azVal; rs->aaRaw[rs->nRow]=azRaw; rs->aaType[rs->nRow]=aType; rs->aaSubtype[rs->nRow]=aSub; rs->nRow++;
    if(p->interruptSeen) break;
  }
  if(rc!=SQLITE_DONE){
    if(pzErr) *pzErr=xstrdup(sqlite3_errmsg(p->db));
  }
  if(p->statsOn) print_stats(p,stmt,0);
  if(p->eScanstats && render){
    fprintf(stderr,"Stats query failed: not available in this build\n");
  }
  { int frc=sqlite3_finalize(stmt); if(rc==SQLITE_DONE) rc=frc; }
  return rc;
}
static int query_collect(Shell *p, const char *zSql, RowSet *rs, char **pzErr){
  sqlite3_stmt *stmt=0; int rc;
  if(pzErr) *pzErr=0;
  rc=sqlite3_prepare_v2(p->db,zSql,-1,&stmt,0);
  if(rc!=SQLITE_OK){ if(pzErr) *pzErr=xstrdup(sqlite3_errmsg(p->db)); if(stmt) sqlite3_finalize(stmt); memset(rs,0,sizeof(*rs)); return rc; }
  if(!stmt){ memset(rs,0,sizeof(*rs)); return SQLITE_OK; }
  return collect_stmt(p,stmt,rs,0,pzErr);
}
/* simple exec ignoring results; returns rc */
static int exec_simple(Shell *p, const char *zSql, char **pzErr){
  char *err=0; int rc;
  if(pzErr) *pzErr=0;
  rc=sqlite3_exec(p->db,zSql,0,0,&err);
  if(rc!=SQLITE_OK && pzErr) *pzErr=xstrdup(err?err:sqlite3_errmsg(p->db));
  if(err) sqlite3_free(err);
  return rc;
}
static void do_eqp_for_sql(Shell *p, const char *zSql, int full){
  char *zQ=sqlite3_mprintf("EXPLAIN QUERY PLAN %s",zSql);
  RowSet rs; char *err=0; int rc=query_collect(p,zQ,&rs,&err);
  sqlite3_free(zQ);
  if(rc==SQLITE_DONE||rc==SQLITE_OK) output_eqp_tree(p,&rs);
  rowset_free(&rs); free(err);
  if(full){
    char *zE=sqlite3_mprintf("EXPLAIN %s",zSql); RowSet rs2; char *e2=0; int rc2=query_collect(p,zE,&rs2,&e2);
    sqlite3_free(zE);
    if(rc2==SQLITE_DONE||rc2==SQLITE_OK) output_explain_bytecode(p,&rs2);
    rowset_free(&rs2); free(e2);
  }
}
static double time_now_sec(void){ struct timeval tv; gettimeofday(&tv,0); return tv.tv_sec+tv.tv_usec/1000000.0; }
