static int trace_callback(unsigned int type, void *C, void *P, void *X){
  Shell *p=(Shell*)C;
  if(!p->traceOut) return 0;
  if(type==SQLITE_TRACE_STMT){
    sqlite3_stmt *stmt=(sqlite3_stmt*)P; const char *z=(const char*)X;
    if(p->traceFlags & 0x20000){ /* expanded */
      char *e=sqlite3_expanded_sql(stmt); if(e){ fprintf(p->traceOut,"%s\n",e); sqlite3_free(e); }
    }else if(!(p->traceFlags & 0x10000)){
      if(z) fprintf(p->traceOut,"%s\n",z);
    }
  }else if(type==SQLITE_TRACE_PROFILE){
    sqlite3_stmt *stmt=(sqlite3_stmt*)P; long long *ns=(long long*)X; char *e=sqlite3_expanded_sql(stmt);
    fprintf(p->traceOut,"%.9f %s\n", ns?(*ns)/1000000000.0:0.0, e?e:"");
