}
static void tokenize_dot_line(const char *zLine, Tokens *t){
  size_t i=0;
  memset(t,0,sizeof(*t));
  if(!zLine) return;
  if(zLine[i]=='.') i++;
  while(zLine[i]){
    Str tok; size_t start;
    while(zLine[i]==' '||zLine[i]=='\t'||zLine[i]=='\r'||zLine[i]=='\n') i++;
    if(!zLine[i]) break;
    start=i; str_init(&tok);
    if(zLine[i]=='\'' || zLine[i]=='"'){
      char quote=zLine[i++]; 
      while(zLine[i] && zLine[i]!=quote){
        if(quote=='"' && zLine[i]=='\\' && zLine[i+1]){
          char c=zLine[++i];
          switch(c){
            case 'a': str_append_c(&tok,'\a'); i++; break;
            case 'b': str_append_c(&tok,'\b'); i++; break;
            case 't': str_append_c(&tok,'\t'); i++; break;
            case 'n': str_append_c(&tok,'\n'); i++; break;
            case 'v': str_append_c(&tok,'\v'); i++; break;
            case 'f': str_append_c(&tok,'\f'); i++; break;
            case 'r': str_append_c(&tok,'\r'); i++; break;
            case 'x': {
              int v=0; i++;
              if(isxdigit((unsigned char)zLine[i])){ v=hexval((unsigned char)zLine[i++]); if(isxdigit((unsigned char)zLine[i])) v=v*16+hexval((unsigned char)zLine[i++]); }
              else v='x';
              str_append_c(&tok,(char)v); break;
            }
            default:
              if(c>='0'&&c<='7'){
                int v=c-'0'; int k; i++;
                for(k=0;k<2 && zLine[i]>='0'&&zLine[i]<='7';k++){ v=v*8+(zLine[i]-'0'); i++; }
                str_append_c(&tok,(char)(v&0xff));
              }else{ str_append_c(&tok,c); i++; }
              break;
          }
          continue;
        }
        str_append_c(&tok,zLine[i++]);
      }
      if(zLine[i]==quote) i++;
    }else{
      while(zLine[i] && zLine[i]!=' '&&zLine[i]!='\t'&&zLine[i]!='\r'&&zLine[i]!='\n') str_append_c(&tok,zLine[i++]);
    }
    tokens_push(t,str_detach(&tok),(int)start);
  }
}
