/* ---------------- dot commands ---------------- */
static int dot_usage(Shell *p, const char *z){
  fprintf(stderr,"%s",z);
  p->nErr++;
  return 1;
}
static const char *bool_onoff(int b){ return b?"on":"off"; }
static void mode_append_quoted_arg(Str *s, const char *z){
  char *q=c_quoted(z); str_append(s,q); free(q);
}
static void append_limits_value(Str *s, ModeSet *m){
  if(m->lineLimit==5 && m->charLimit==300 && m->titleLimit==20) str_append(s,"on");
  else if(m->lineLimit==0 && m->charLimit==0 && m->titleLimit==0) str_append(s,"off");
  else str_appendf(s,"%d,%d,%d",m->lineLimit,m->charLimit,m->titleLimit);
}
static char *mode_verbose_string(Shell *p, ModeSet *m, int verbose){
  Str s; str_init(&s);
  str_append(&s,".mode ");
  if(p->modeOnceActive) str_append(&s,"--once ");
  str_append(&s,mode_kind_name(m->kind));
  if(verbose){
    str_append(&s," --align "); mode_append_quoted_arg(&s,m->zAlign);
    str_appendf(&s," --border %s",bool_onoff(m->border));
    str_appendf(&s," --blob-quote %s",blobquote_name(m->blobQuote));
    str_append(&s," --colsep "); mode_append_quoted_arg(&s,m->zColSep);
    str_appendf(&s," --escape %s",escape_name(m->escape));
    str_append(&s," --limits "); append_limits_value(&s,m);
    str_appendf(&s," --multiinsert %d",m->multiInsert);
    str_append(&s," --null "); mode_append_quoted_arg(&s,m->zNull);
    str_appendf(&s," --quote %s",quote_name(m->quote));
    str_append(&s," --rowsep "); mode_append_quoted_arg(&s,m->zRowSep);
    if(m->screenWidth<0) str_append(&s," --sw auto");
    else str_appendf(&s," --sw %d",m->screenWidth);
    str_append(&s," --tablename "); mode_append_quoted_arg(&s,m->zTableName);
    str_appendf(&s," --textjsonb %s",bool_onoff(m->textJsonb));
    if(mode_titles_applicable(m->kind)) str_appendf(&s," --titles %s",title_name(m->title));
    str_append(&s," --widths ");
    if(m->nWidth==0) str_append(&s,"\"\"");
    else { int i; for(i=0;i<m->nWidth;i++){ if(i)str_append_c(&s,','); str_appendf(&s,"%d",m->aWidth[i]); } }
    str_appendf(&s," --wordwrap %s",bool_onoff(m->wordWrap));
    if(m->wrap) str_appendf(&s," --wrap %d",m->wrap);
    str_append_c(&s,'\n');
    return str_detach(&s);
  }
  /* non-verbose: append relevant differences from the kind's preset */
  {
    ModeSet pre; memset(&pre,0,sizeof(pre)); modeset_preset(&pre,m->kind);
    int isColumnar = (m->kind==MODE_Box||m->kind==MODE_Qbox||m->kind==MODE_Table||m->kind==MODE_Markdown||m->kind==MODE_Psql||m->kind==MODE_Column||m->kind==MODE_Split);
    int isSimple = !isColumnar;
    /* tty preset detection: if current equals tty-expansion of qbox, use that as canonical diff base against qbox */
    if(m->kind==MODE_C||m->kind==MODE_Tcl){
      if(m->blobQuote==B_Tcl) str_append(&s," --blob-quote tcl");
    }
    if(m->kind==MODE_Insert){
      str_append(&s," --tablename "); mode_append_quoted_arg(&s,m->zTableName);
    }
    if(m->kind==MODE_Split && m->screenWidth<0) str_append(&s," --sw auto");
    if(strcmp(m->zAlign,pre.zAlign)&&isColumnar){ str_append(&s," --align "); mode_append_quoted_arg(&s,m->zAlign); }
    if(m->border!=pre.border && (m->kind==MODE_Box||m->kind==MODE_Qbox||m->kind==MODE_Table||m->kind==MODE_Psql||m->kind==MODE_Markdown)) str_appendf(&s," --border %s",bool_onoff(m->border));
    if(m->blobQuote!=pre.blobQuote) str_appendf(&s," --blob-quote %s",blobquote_name(m->blobQuote));
    if(strcmp(m->zColSep,pre.zColSep) && (isSimple)) { str_append(&s," --colsep "); mode_append_quoted_arg(&s,m->zColSep); }
    if(m->escape!=pre.escape) str_appendf(&s," --escape %s",escape_name(m->escape));
    {
      int limitsDiff = (m->lineLimit!=pre.lineLimit||m->charLimit!=pre.charLimit||m->titleLimit!=pre.titleLimit);
      int limitsRelevant = isColumnar || m->kind==MODE_Line || m->charLimit!=pre.charLimit;
      if(limitsDiff && limitsRelevant){ str_append(&s," --limits "); append_limits_value(&s,m); }
    }
    if(m->multiInsert!=pre.multiInsert && m->kind==MODE_Insert) str_appendf(&s," --multiinsert %d",m->multiInsert);
    if(strcmp(m->zNull,pre.zNull)) { str_append(&s," --null "); mode_append_quoted_arg(&s,m->zNull); }
    if(m->quote!=pre.quote) str_appendf(&s," --quote %s",quote_name(m->quote));
    if(strcmp(m->zRowSep,pre.zRowSep) && isSimple){ str_append(&s," --rowsep "); mode_append_quoted_arg(&s,m->zRowSep); }
    if(m->screenWidth!=pre.screenWidth){
      if(!(m->kind==MODE_Split && m->screenWidth<0)){
        if(m->screenWidth<0) str_append(&s," --sw auto"); else str_appendf(&s," --sw %d",m->screenWidth);
      }
    }
    if(m->textJsonb!=pre.textJsonb) str_appendf(&s," --textjsonb %s",bool_onoff(m->textJsonb));
    if(mode_titles_applicable(m->kind) && m->title!=pre.title) str_appendf(&s," --title %s",title_name(m->title));
    if(m->nWidth>0 && isColumnar){
      str_append(&s," --widths "); { int i; for(i=0;i<m->nWidth;i++){ if(i)str_append_c(&s,','); str_appendf(&s,"%d",m->aWidth[i]); } }
    }
    if(m->wordWrap!=pre.wordWrap && isColumnar) str_appendf(&s," --wordwrap %s",bool_onoff(m->wordWrap));
    if(m->wrap && isColumnar) str_appendf(&s," --wrap %d",m->wrap);
    /* tty/qbox special ordering correction: reference prints
    ** ".mode qbox --limits on --quote relaxed --sw auto --textjsonb on" which matches field order above */
    modeset_free(&pre);
  }
  str_append_c(&s,'\n');
  return str_detach(&s);
}
