static int mode_missing_arg(Shell *p, const char *zLine, int lineNo, Tokens *t, int i){
  dot_error(p,zLine,lineNo,t->aCol[i],"missing argument",0);
  return 1;
}
static int handle_mode_cmd(Shell *p, Tokens *t, const char *zLine, InputCtx *ctx){
  int i; int verbose=0; int modeSeen=0; int positionalAllowed=0;
  int lineNo=ctx?ctx->lineno:p->curLineNo;
  if(t->n==1){ print_mode(p,0); return 0; }
  for(i=1;i<t->n;i++){
    char *arg=t->az[i]; int col=t->aCol[i];
    if(strcmp(arg,"--list")==0){
      out_write(p,"available modes: ascii box c column count csv html insert jatom jobject json line list markdown off psql qbox quote split table tabs tcl batch tty\n");
      positionalAllowed=0; continue;
    }
    if(strcmp(arg,"-v")==0||strcmp(arg,"--verbose")==0){ verbose=1; positionalAllowed=0; continue; }
    if(arg[0]=='-'){
      const char *opt;
      if(arg[1]!='-'){ dot_error(p,zLine,lineNo,col,"bad option","Use \".help .mode\" for more info"); return 1; }
      opt=arg+2;
      positionalAllowed=0;
      if(!strcmp(opt,"once")){
        if(!p->hasSavedMode){ memset(&p->savedMode,0,sizeof(p->savedMode)); modeset_copy(&p->savedMode,&p->mode); p->hasSavedMode=1; p->modeOnceActive=1; }
        continue;
      }
      if(!strcmp(opt,"reset")){
        int k=p->mode.kind; modeset_preset(&p->mode,k); continue;
      }
      if(!strcmp(opt,"ww")){ p->mode.wordWrap=1; continue; }
      if(!strcmp(opt,"list")){
        out_write(p,"available modes: ascii box c column count csv html insert jatom jobject json line list markdown off psql qbox quote split table tabs tcl batch tty\n"); continue;
      }
      if(!strcmp(opt,"verbose")){ verbose=1; continue; }
      /* all remaining options need an argument */
      {
        int known = !strcmp(opt,"align")||!strcmp(opt,"blob-quote")||!strcmp(opt,"border")||!strcmp(opt,"charlimit")||!strcmp(opt,"colsep")||!strcmp(opt,"escape")||!strcmp(opt,"linelimit")||!strcmp(opt,"limits")||!strcmp(opt,"multiinsert")||!strcmp(opt,"null")||!strcmp(opt,"quote")||!strcmp(opt,"rowsep")||!strcmp(opt,"sw")||!strcmp(opt,"screenwidth")||!strcmp(opt,"tablename")||!strcmp(opt,"tag")||!strcmp(opt,"textjsonb")||!strcmp(opt,"title")||!strcmp(opt,"titles")||!strcmp(opt,"titlelimit")||!strcmp(opt,"width")||!strcmp(opt,"widths")||!strcmp(opt,"wordwrap")||!strcmp(opt,"wrap");
        char *val; int vcol;
        if(!known){ dot_error(p,zLine,lineNo,col,"bad option","Use \".help .mode\" for more info"); return 1; }
        if(i+1>=t->n) return mode_missing_arg(p,zLine,lineNo,t,i);
        val=t->az[++i]; vcol=t->aCol[i];
        if(!strcmp(opt,"align")){
          Str a; int bad=0; const char *c; str_init(&a);
          for(c=val;*c;c++){ if(*c=='L'||*c=='C'||*c=='R') str_append_c(&a,*c); else if(*c=='l')str_append_c(&a,'L'); else if(*c=='c')str_append_c(&a,'C'); else if(*c=='r')str_append_c(&a,'R'); else { str_append_c(&a,'L'); bad=1; } }
          free(p->mode.zAlign); p->mode.zAlign=str_detach(&a);
          if(bad){ dot_error(p,zLine,lineNo,vcol,"bad alignment string","Should contain only characters L, C, and R."); return 1; }
        }else if(!strcmp(opt,"blob-quote")){
          if(!strcmp(val,"auto"))p->mode.blobQuote=B_Auto;
          else if(!strcmp(val,"text"))p->mode.blobQuote=B_Text;
          else if(!strcmp(val,"sql"))p->mode.blobQuote=B_Sql;
          else if(!strcmp(val,"hex"))p->mode.blobQuote=B_Hex;
          else if(!strcmp(val,"tcl"))p->mode.blobQuote=B_Tcl;
          else if(!strcmp(val,"json"))p->mode.blobQuote=B_Json;
          else if(!strcmp(val,"size"))p->mode.blobQuote=B_Size;
          /* bogus silently ignored in reference */
        }else if(!strcmp(opt,"border")){
          p->mode.border = (strcmp(val,"on")==0);
        }else if(!strcmp(opt,"charlimit")) p->mode.charLimit=atoi(val);
        else if(!strcmp(opt,"colsep")){ free(p->mode.zColSep); p->mode.zColSep=xstrdup(val); }
        else if(!strcmp(opt,"escape")){
          if(!strcmp(val,"off"))p->mode.escape=ESC_Off;
          else if(!strcmp(val,"ascii"))p->mode.escape=ESC_Ascii;
          else if(!strcmp(val,"symbol"))p->mode.escape=ESC_Symbol;
          else { dot_error(p,zLine,lineNo,vcol,"unknown escape type","should be off, ascii, or symbol"); return 1; }
        }else if(!strcmp(opt,"linelimit")) p->mode.lineLimit=atoi(val);
        else if(!strcmp(opt,"limits")){
          if(!strcmp(val,"off")){ p->mode.lineLimit=0;p->mode.charLimit=0;p->mode.titleLimit=0; }
          else if(!strcmp(val,"on")){ p->mode.lineLimit=5;p->mode.charLimit=300;p->mode.titleLimit=20; }
