/* Insert schema qualifier before object name in CREATE ... sql */
static char *qualify_schema_sql(const char *sql, const char *dbn){
  /* find object name: after CREATE [UNIQUE|TEMP|TEMPORARY|VIRTUAL] TABLE|INDEX|VIEW|TRIGGER [IF NOT EXISTS] */
  const char *s=sql; Str out; int i;
  static const char *kws[]={"IF","NOT","EXISTS",0};
  (void)kws;
  str_init(&out);
  /* token scan by words, preserving original up to name start */
  {
    const char *p=s; int wordIndex=0; const char *nameStart=0;
    while(*p){
      while(isspace((unsigned char)*p)) p++;
      if(!isalpha((unsigned char)*p)&&*p!='_'&&*p!='"'&&*p!='\''&&*p!='['&&*p!='`') break;
      if(*p=='"'||*p=='\''||*p=='['||*p=='`'){ nameStart=p; break; }
      { const char *w=p; char word[32]; size_t n=0; while(isalnum((unsigned char)*p)||*p=='_'){ if(n+1<sizeof(word)) word[n++]=toupper((unsigned char)*p); p++; } word[n]=0;
        wordIndex++;
        if(wordIndex==1 && strcmp(word,"CREATE")) break;
        if(!strcmp(word,"TABLE")||!strcmp(word,"INDEX")||!strcmp(word,"VIEW")||!strcmp(word,"TRIGGER")){
          /* name is next, skipping IF NOT EXISTS */
          const char *q=p; int k;
          for(k=0;k<3;k++){
            const char *wq; char w2[16]; size_t nn=0;
            while(isspace((unsigned char)*q)) q++;
            wq=q; while(isalpha((unsigned char)*q)){ if(nn+1<sizeof(w2))w2[nn++]=toupper((unsigned char)*q); q++; } w2[nn]=0;
            if(!strcmp(w2,"IF")||!strcmp(w2,"NOT")||!strcmp(w2,"EXISTS")){ p=q; continue; }
            q=wq; break;
          }
          while(isspace((unsigned char)*q)) q++;
          nameStart=q; break;
        }
        (void)w;
      }
    }
    if(nameStart){
      str_append_n(&out,sql,(size_t)(nameStart-sql));
      str_append(&out,dbn); str_append_c(&out,'.');
      str_append(&out,nameStart);
      return str_detach(&out);
    }
  }
  str_free(&out);
  return xstrdup(sql);
  (void)i;
}
static char *format_schema_indent(const char *zSql){
  /* Reformats long CREATE TABLE statements; heuristic observed from .schema --indent */
  const char *s=zSql;
  int hasNl=strchr(s,'\n')!=0;
  if(hasNl){
    /* strip leading spaces on continuation lines, drop newline right after '(' and right before ')' */
    Str out; size_t i=0; str_init(&out);
    while(s[i]){
      if(s[i]=='('){ str_append_c(&out,s[i++]); if(s[i]=='\n'){ i++; while(isspace((unsigned char)s[i])&&s[i]!='\n')i++; } continue; }
      if(s[i]=='\n'){
        size_t j=i+1; while(s[j]==' '||s[j]=='\t')j++;
        if(s[j]==')'){ i=j; continue; }
        str_append_c(&out,'\n'); i=j; continue;
      }
      str_append_c(&out,s[i++]);
    }
    return str_detach(&out);
  }
  if(strlen(s)<=79) return xstrdup(s);
  {
    char kw[16]; const char *p;
    first_keyword(s,kw,sizeof(kw));
    if(strcasecmp(kw,"CREATE")) return xstrdup(s);
    p=strchr(s,'(');
    if(!p) return xstrdup(s);
    /* find matching close paren at depth 0 (last close that returns depth0 from first open) */
    { int depth=0; const char *q=p; const char *close=0; int inSQ=0,inDQ=0;
      for(;*q;q++){
        if(inSQ){ if(*q=='\''){ if(q[1]=='\'')q++; else inSQ=0; } continue; }
        if(inDQ){ if(*q=='"') inDQ=0; continue; }
        if(*q=='\'')inSQ=1; else if(*q=='"')inDQ=1;
        else if(*q=='(')depth++; else if(*q==')'){ depth--; if(depth==0){close=q;break;} }
      }
      if(!close) return xstrdup(s);
      {
        Str out; const char *elemStart=p+1; const char *c; int d2=0; int first=1;
        str_init(&out); str_append_n(&out,s,(size_t)(p-s)+1); str_append_c(&out,'\n');
        inSQ=0;inDQ=0;
        for(c=p+1;;c++){
          int isEnd=(c==close);
          if(!isEnd){
            if(inSQ){ if(*c=='\''){ if(c[1]=='\'')c++; else inSQ=0; } continue; }
            if(inDQ){ if(*c=='"')inDQ=0; continue; }
            if(*c=='\'')inSQ=1; else if(*c=='"')inDQ=1;
            else if(*c=='(')d2++; else if(*c==')')d2--;
          }
          if(isEnd || (*c==','&&d2==0&&!inSQ&&!inDQ)){
            const char *e=elemStart; const char *ee=c;
            while(e<ee&&isspace((unsigned char)*e))e++;
            while(ee>e&&isspace((unsigned char)ee[-1]))ee--;
            if(!first) str_append(&out,",\n");
            str_append(&out,"  "); str_append_n(&out,e,(size_t)(ee-e));
            first=0; elemStart=c+1;
            if(isEnd) break;
          }
        }
        str_append_c(&out,'\n'); str_append(&out,close);
        return str_detach(&out);
      }
    }
  }
}
