static void dump_table_data(Shell *p, const char *zTable, const char *zTableSql, int preserve){
  /* column info */
  char *qinfo=sqlite3_mprintf("PRAGMA table_xinfo(\"%w\");",zTable);
  RowSet info; char *err=0; int i; Str cols; int nCol=0; char **azCol=0; int isIPK=0; int pkCount=0; int withoutRowid=0;
