    int pk=info.nCol>5?atoi(info.aaRaw[i][5]):0;
    const char *ctype=info.nCol>2?info.aaRaw[i][2]:"";
    if(pk) pkCount++;
    if(pk==1 && strcasecmp(ctype,"INTEGER")==0) isIPK=1;
    if(hidden>=2) continue; /* generated */
    azCol[nCol++]=xstrdup(info.aaRaw[i][1]);
