    for(i=0;i<nCol;i++){ char *qi=quote_identifier(azCol[i]); if(i)str_append_c(&sel,','); str_append(&sel,qi); free(qi); }
    if(nCol==0) str_append_c(&sel,'*');
    { char *qt=quote_identifier(zTable); str_append(&sel," FROM "); str_append(&sel,qt); free(qt); }
    zSel=str_detach(&sel);
  }
