    char *zQT=quote_identifier(zTable);
    while((rc=sqlite3_step(stmt))==SQLITE_ROW){
      int ncol=sqlite3_column_count(stmt); int c;
      out_printf(p,"INSERT INTO %s",zQT);
      if(preserve){
        out_write(p,"(");
        {
          int first=1;
          if(!withoutRowid && !isIPK){ out_write(p,"rowid"); first=0; }
          for(i=0;i<nCol;i++){ char *qi=quote_identifier(azCol[i]); if(!first)out_write(p,","); out_write(p,qi); free(qi); first=0; }
        }
