        else if(type==SQLITE_FLOAT){ char *fr=format_real(sqlite3_column_double(stmt,c)); out_write(p,fr); free(fr); }
        else if(type==SQLITE_BLOB){ const unsigned char *b=(const unsigned char*)sqlite3_column_blob(stmt,c); int nb=sqlite3_column_bytes(stmt,c); int k; out_write(p,"x'"); for(k=0;k<nb;k++) out_printf(p,"%02x",b[k]); out_write(p,"'"); }
