typedef struct CsvParser CsvParser;
struct CsvParser {
  const unsigned char *data; size_t len; size_t pos;
  char colSep; char rowSep; int useCsv; char esc; char qesc;
  int lineNo;      /* current physical line (1-based for next record) */
  int totalLines;  /* physical lines consumed */
