static int csv_at_rowsep(CsvParser *p){
  if(p->pos>=p->len) return 0;
  if(p->rowSep=='\n'){
    if(p->data[p->pos]=='\n') return 1;
    if(p->data[p->pos]=='\r' && p->pos+1<p->len && p->data[p->pos+1]=='\n') return 2;
    return 0;
  }
  if(p->rowSep=='\r'){
    if(p->data[p->pos]=='\r' && p->pos+1<p->len && p->data[p->pos+1]=='\n') return 2;
    if(p->data[p->pos]=='\r') return 1;
    return 0;
  }
  return p->data[p->pos]==(unsigned char)p->rowSep ? 1:0;
}
static int csv_next_record(CsvParser *p, CsvRecord *rec){
  Str field; int done=0;
