static int do_dbconfig_cmd(Shell *p, Tokens *t, const char *zLine, InputCtx *ctx){
  typedef struct Cfg Cfg;
  struct Cfg { const char *name; int op; int isInt; };
  static const Cfg aCfg[]={
    {"attach_create",-1,0},{"attach_write",-2,0},{"comments",-3,0},
    {"defensive",SQLITE_DBCONFIG_DEFENSIVE,0},{"dqs_ddl",SQLITE_DBCONFIG_DQS_DDL,0},
    {"dqs_dml",SQLITE_DBCONFIG_DQS_DML,0},{"enable_fkey",SQLITE_DBCONFIG_ENABLE_FKEY,0},
    {"enable_qpsg",SQLITE_DBCONFIG_ENABLE_QPSG,0},{"enable_trigger",SQLITE_DBCONFIG_ENABLE_TRIGGER,0},
    {"enable_view",SQLITE_DBCONFIG_ENABLE_VIEW,0},{"fts3_tokenizer",SQLITE_DBCONFIG_ENABLE_FTS3_TOKENIZER,0},
    {"fp_digits",-4,1},{"legacy_alter_table",SQLITE_DBCONFIG_LEGACY_ALTER_TABLE,0},
    {"legacy_file_format",SQLITE_DBCONFIG_LEGACY_FILE_FORMAT,0},{"load_extension",SQLITE_DBCONFIG_ENABLE_LOAD_EXTENSION,0},
    {"no_ckpt_on_close",SQLITE_DBCONFIG_NO_CKPT_ON_CLOSE,0},{"reset_database",SQLITE_DBCONFIG_RESET_DATABASE,0},
    {"reverse_scanorder",-5,0},{"stmt_scanstatus",-6,0},{"trigger_eqp",SQLITE_DBCONFIG_TRIGGER_EQP,0},
    {"trusted_schema",SQLITE_DBCONFIG_TRUSTED_SCHEMA,0},{"writable_schema",SQLITE_DBCONFIG_WRITABLE_SCHEMA,0},{0,0,0}};
  static int stmtScanstatusCfg=0;
  int i;
  if(t->n==1){
    for(i=0;aCfg[i].name;i++){
      int outv=0;
      if(aCfg[i].op==-1)outv=p->cfgAttachCreate; else if(aCfg[i].op==-2)outv=p->cfgAttachWrite;
      else if(aCfg[i].op==-3)outv=p->cfgComments; else if(aCfg[i].op==-4)outv=p->cfgFpDigits;
      else if(aCfg[i].op==-5)outv=p->cfgReverseScanorder; else if(aCfg[i].op==-6)outv=stmtScanstatusCfg;
      else { sqlite3_db_config(p->db,aCfg[i].op,-1,&outv); }
      if(aCfg[i].isInt) out_printf(p,"%21s %d\n",aCfg[i].name,outv);
      else out_printf(p,"%21s %s\n",aCfg[i].name,bool_onoff(outv));
    }
    return 0;
  }
  for(i=0;aCfg[i].name;i++){
    if(!strcmp(t->az[1],aCfg[i].name)){
      int outv=0;
      if(t->n>=3){
        if(aCfg[i].isInt){ p->cfgFpDigits=atoi(t->az[2]); outv=p->cfgFpDigits; }
        else {
          int v=boolean_or_error(p,t->az[2]);
          if(aCfg[i].op==-1)p->cfgAttachCreate=v; else if(aCfg[i].op==-2)p->cfgAttachWrite=v;
          else if(aCfg[i].op==-3)p->cfgComments=v; else if(aCfg[i].op==-5)p->cfgReverseScanorder=v;
          else if(aCfg[i].op==-6)stmtScanstatusCfg=v;
          else sqlite3_db_config(p->db,aCfg[i].op,v,&outv);
          if(aCfg[i].op<0) outv=v;
        }
      }else{
        if(aCfg[i].op==-1)outv=p->cfgAttachCreate; else if(aCfg[i].op==-2)outv=p->cfgAttachWrite;
        else if(aCfg[i].op==-3)outv=p->cfgComments; else if(aCfg[i].op==-4)outv=p->cfgFpDigits;
        else if(aCfg[i].op==-5)outv=p->cfgReverseScanorder; else if(aCfg[i].op==-6)outv=stmtScanstatusCfg;
        else sqlite3_db_config(p->db,aCfg[i].op,-1,&outv);
      }
      if(aCfg[i].isInt) out_printf(p,"%21s %d\n",aCfg[i].name,outv);
      else out_printf(p,"%21s %s\n",aCfg[i].name,bool_onoff(outv));
      return 0;
    }
  }
  {
    int before=p->nErr;
    dot_error(p,zLine,ctx?ctx->lineno:p->curLineNo,t->aCol[1],"unknown dbconfig","Enter \".dbconfig\" with no arguments for a list");
    p->nErr=before; /* reference does not count this as a fatal error */
  }
  return 0;
}
static int do_limit_cmd(Shell *p, Tokens *t){
  typedef struct Lim Lim;
  struct Lim { const char *name; int op; int defval; };
  static const Lim aLim[]={
    {"length",SQLITE_LIMIT_LENGTH,1000000000},{"sql_length",SQLITE_LIMIT_SQL_LENGTH,1000000000},
    {"column",SQLITE_LIMIT_COLUMN,2000},{"expr_depth",SQLITE_LIMIT_EXPR_DEPTH,1000},
    {"parser_depth",-1,2500},{"compound_select",SQLITE_LIMIT_COMPOUND_SELECT,500},
    {"vdbe_op",SQLITE_LIMIT_VDBE_OP,250000000},{"function_arg",SQLITE_LIMIT_FUNCTION_ARG,1000},
    {"attached",SQLITE_LIMIT_ATTACHED,10},{"like_pattern_length",SQLITE_LIMIT_LIKE_PATTERN_LENGTH,50000},
    {"variable_number",SQLITE_LIMIT_VARIABLE_NUMBER,32766},{"trigger_depth",SQLITE_LIMIT_TRIGGER_DEPTH,1000},
    {"worker_threads",SQLITE_LIMIT_WORKER_THREADS,0},{0,0,0}};
  int i;
  if(t->n==1){
    for(i=0;aLim[i].name;i++){
      int v;
      if(aLim[i].op==-1) v=p->limitParserDepth;
      else if(aLim[i].op==SQLITE_LIMIT_FUNCTION_ARG){ static int shadowFA=1000; v=shadowFA; }
      else v=sqlite3_limit(p->db,aLim[i].op,-1);
      out_printf(p,"%21s %d\n",aLim[i].name,v);
    }
    return 0;
  }
  if(t->n>3){ fprintf(stderr,"Usage: .limit NAME ?NEW-VALUE?\n"); p->nErr++; return 1; }
  for(i=0;aLim[i].name;i++){
    /* names are case-insensitive in reference (LENGTH works) */
    if(!strcasecmp(t->az[1],aLim[i].name)){
      int v;
      if(t->n==3){
        int nv=atoi(t->az[2]);
        if(aLim[i].op==-1){ if(nv>=0)p->limitParserDepth=nv; v=p->limitParserDepth; }
        else if(aLim[i].op==SQLITE_LIMIT_FUNCTION_ARG){ static int shadowFA2=1000; /* keep simple: actual limit may be lowered */ sqlite3_limit(p->db,aLim[i].op,nv); v=nv<0?shadowFA2:nv; shadowFA2=v; }
        else v=sqlite3_limit(p->db,aLim[i].op,nv);
        (void)v;
        return 0;
      }
      if(aLim[i].op==-1) v=p->limitParserDepth;
      else if(aLim[i].op==SQLITE_LIMIT_FUNCTION_ARG) v=1000;
      else v=sqlite3_limit(p->db,aLim[i].op,-1);
      out_printf(p,"%21s %d\n",aLim[i].name,v);
      return 0;
    }
  }
  fprintf(stderr,"unknown limit: \"%s\"\nenter \".limits\" with no arguments for a list.\n",t->az[1]);
  p->nErr++; return 1;
}
static void ensure_param_table(Shell *p){
  exec_simple(p,"CREATE TEMP TABLE IF NOT EXISTS sqlite_parameters(\n  key TEXT PRIMARY KEY,\n  value\n) WITHOUT ROWID;",0);
  p->paramsInit=1;
}
static int param_table_exists(Shell *p){
  RowSet rs; char *e=0; int ok=0;
  if(query_collect(p,"SELECT 1 FROM sqlite_temp_schema WHERE type='table' AND name='sqlite_parameters';",&rs,&e)==SQLITE_DONE&&rs.nRow>0)ok=1;
  rowset_free(&rs); free(e); return ok;
}
static int do_parameter_cmd(Shell *p, Tokens *t){
  const char *zHelp=".parameter CMD ...       Manage SQL parameter bindings\n   clear                   Erase all bindings\n   init                    Initialize the TEMP table that holds bindings\n   list                    List the current parameter bindings\n   set PARAMETER VALUE     Given SQL parameter PARAMETER a value of VALUE\n                           PARAMETER should start with one of: $ : @ ?\n   unset PARAMETER         Remove PARAMETER from the binding table\n";
  if(t->n<2){ out_write(p,zHelp); return 0; }
  if(!strcmp(t->az[1],"init")){ ensure_param_table(p); return 0; }
  if(!strcmp(t->az[1],"clear")){ if(param_table_exists(p)) exec_simple(p,"DELETE FROM sqlite_parameters;",0); return 0; }
  if(!strcmp(t->az[1],"list")){
    RowSet rs; char *e=0; int i;
    if(!param_table_exists(p)) return 0;
    if(query_collect(p,"SELECT key, quote(value) FROM sqlite_parameters ORDER BY key;",&rs,&e)==SQLITE_DONE){
      for(i=0;i<rs.nRow;i++) out_printf(p,"%s %s\n",rs.aaRaw[i][0],rs.aaRaw[i][1]);
    }
    rowset_free(&rs); free(e); return 0;
  }
  if(!strcmp(t->az[1],"set")){
    char *q; char *e=0; int rc;
    if(t->n!=4){ out_write(p,zHelp); return 0; }
    ensure_param_table(p);
    q=sqlite3_mprintf("INSERT OR REPLACE INTO sqlite_parameters(key,value) VALUES('%q',%s);",t->az[2],t->az[3]);
    rc=exec_simple(p,q,&e); sqlite3_free(q); free(e);
    if(rc!=SQLITE_OK){
      sqlite3_stmt *st=0;
      if(sqlite3_prepare_v2(p->db,"INSERT OR REPLACE INTO sqlite_parameters(key,value) VALUES(?1,?2);",-1,&st,0)==SQLITE_OK){
        sqlite3_bind_text(st,1,t->az[2],-1,SQLITE_TRANSIENT); sqlite3_bind_text(st,2,t->az[3],-1,SQLITE_TRANSIENT); sqlite3_step(st); sqlite3_finalize(st);
      }
    }
    return 0;
  }
  if(!strcmp(t->az[1],"unset")){
    char *q;
    if(t->n!=3||!param_table_exists(p)){ if(t->n!=3) out_write(p,zHelp); return 0; }
    q=sqlite3_mprintf("DELETE FROM sqlite_parameters WHERE key='%q';",t->az[2]); exec_simple(p,q,0); sqlite3_free(q); return 0;
  }
  out_write(p,zHelp);
  return 0;
}
static void do_prompt_cmd(Shell *p, Tokens *t, const char *zLine, InputCtx *ctx){
  int i; int idx=1;
  if(t->n>=2 && !strcmp(t->az[1],"--show")){
    out_printf(p,"Main prompt:  '%s'\nContinuation: '%s'\n",p->zPrompt,p->zContinuePrompt); return;
  }
  if(t->n>=2 && !strcmp(t->az[1],"--hard-reset")){
    unsetenv("SQLITE_PS1"); unsetenv("SQLITE_PS2");
    free(p->zPrompt); p->zPrompt=xstrdup("SQLite /f> ");
    free(p->zContinuePrompt); p->zContinuePrompt=xstrdup("/B.../H> ");
    return;
  }
  if(t->n>=2 && !strcmp(t->az[1],"--reset")){
    const char *ps1=getenv("SQLITE_PS1"); const char *ps2=getenv("SQLITE_PS2");
    free(p->zPrompt); p->zPrompt=xstrdup(ps1?ps1:"SQLite /f> ");
    free(p->zContinuePrompt); p->zContinuePrompt=xstrdup(ps2?ps2:"/B.../H> ");
    return;
  }
  if(t->n>=2 && !strcmp(t->az[1],"--")) idx=2;
  else if(t->n>=2 && t->az[1][0]=='-'&&t->az[1][1]){
    dot_error(p,zLine,ctx?ctx->lineno:p->curLineNo,t->aCol[1],"unknown option",0); return;
