static int do_trace_cmd(Shell *p, Tokens *t){
  int i; const char *dest=0; int flags=0;
  if(t->n==1){ /* turns off? no change observed when previously off; treat as off */
    dest="off";
  }
  for(i=1;i<t->n;i++){
    if(!strcmp(t->az[i],"--expanded")) flags|=0x20000|SQLITE_TRACE_STMT;
    else if(!strcmp(t->az[i],"--plain")) flags|=0x10000;
    else if(!strcmp(t->az[i],"--stmt")) flags|=SQLITE_TRACE_STMT;
    else if(!strcmp(t->az[i],"--profile")) flags|=SQLITE_TRACE_PROFILE;
    else if(!strcmp(t->az[i],"--row")) flags|=SQLITE_TRACE_ROW;
    else if(!strcmp(t->az[i],"--close")) flags|=SQLITE_TRACE_CLOSE;
    else dest=t->az[i];
  }
  /* close old trace file if ours */
  if(p->traceOut && p->traceOut!=stdout && p->traceOut!=stderr) fclose(p->traceOut);
  p->traceOut=0; p->traceFlags=0;
  if(p->db) sqlite3_trace_v2(p->db,0,0,0);
  if(dest&&!strcmp(dest,"off")) return 0;
  if(!dest) return 0;
  if(flags==0) flags=SQLITE_TRACE_STMT;
  p->traceFlags=flags;
  if(!strcmp(dest,"stdout")) p->traceOut=stdout;
  else if(!strcmp(dest,"stderr")) p->traceOut=stderr;
  else {
    p->traceOut=fopen(dest,"w");
    if(!p->traceOut){ fprintf(stderr,"Error: cannot open \"%s\"\n",dest); p->nErr++; p->traceFlags=0; return 1; }
  }
  if(p->db) sqlite3_trace_v2(p->db,(unsigned)(flags&0xffff),trace_callback,p);
  return 0;
