        case 2: modeset_preset(&p->mode,a->ivalue); break;
        case 3: p->mode.title=a->ivalue?(p->mode.title==T_Off?T_On:p->mode.title):T_Off; break;
        case 4: p->bailOn=a->ivalue; break;
        case 5: p->echoOn=a->ivalue; break;
        case 6: p->statsOn=a->ivalue; break;
        case 7: free(p->mode.zColSep); p->mode.zColSep=xstrdup(a->svalue); break;
        case 8: free(p->mode.zRowSep); p->mode.zRowSep=xstrdup(a->svalue); break;
        case 9: free(p->mode.zNull); p->mode.zNull=xstrdup(a->svalue); break;
        case 10: p->mode.escape=a->ivalue; break;
        case 11: p->mode.screenWidth=a->ivalue; break;
      }
      if(had) startupHadError=1;
      if(p->exitImmediately) goto shutdown;
      if(p->stopInput) { /* .quit inside a -cmd: stop program */ if(!p->exitImmediately) p->exitImmediately=1; goto shutdown; }
      if(had && p->bailOn){ p->exitCode=1; goto shutdown; }
    }
  }
