    input_free(ctx);
  }
  shutdown:
  if(p->testcaseActive){
    char *discard=testcase_finish_capture(p,1); free(discard);
  }
  if(p->nTestcase>0){
    printf("%d test%s run with %d error%s\n",p->nTestcase,p->nTestcase==1?"":"s",p->nTestcaseErr,p->nTestcaseErr==1?"":"s");
