  }
  write_history_file(p);
  if(!p->exitImmediately && p->exitCode==0 && p->nErr>0) p->exitCode=1;
  {
    int rc=p->exitCode;
    close_current_output(p);
    if(p->logOut&&p->logOut!=stdout&&p->logOut!=stderr) fclose(p->logOut);
    if(p->traceOut&&p->traceOut!=stdout&&p->traceOut!=stderr) fclose(p->traceOut);
    close_all_connections(p);
    free(sqlArgs); free(sqlArgIdx); free(zInitFile);
    return rc&0xff;
  }
}
