/* ---------------- startup / main ---------------- */
typedef struct StartupAction StartupAction;
struct StartupAction {
  int type; /* 1 cmd,2 mode,3 header,4 bail,5 echo,6 stats,7 colsep,8 rowsep,9 null,10 escape,11 screenwidth */
  int ivalue;
  char *svalue;
  int argvIndex;
  StartupAction *next;
};
static StartupAction *gActionsHead=0,*gActionsTail=0;
static void add_action(int type,int ivalue,const char *svalue,int argvIndex){
  StartupAction *a=(StartupAction*)xmalloc(sizeof(StartupAction)); memset(a,0,sizeof(*a));
  a->type=type;a->ivalue=ivalue;a->svalue=svalue?xstrdup(svalue):0;a->argvIndex=argvIndex;
  if(gActionsTail)gActionsTail->next=a; else gActionsHead=a; gActionsTail=a;
}
static volatile sig_atomic_t gSigInt=0;
static void sigint_handler(int sig){
  (void)sig; gSigInt=1;
  if(gShell){ gShell->interruptSeen=1; if(gShell->db) sqlite3_interrupt(gShell->db); }
}
static char *find_resource_file(Shell *p, const char *zInit){
  struct passwd *pw; const char *home; const char *xdg;
  (void)p;
  if(zInit) return xstrdup(zInit);
  pw=getpwuid(getuid()); home=pw?pw->pw_dir:getenv("HOME");
  if(!home) return 0;
  xdg=getenv("XDG_CONFIG_HOME");
  {
    char *cfg;
    if(xdg&&xdg[0]) cfg=sqlite3_mprintf("%s/sqlite3/sqliterc",xdg);
    else cfg=sqlite3_mprintf("%s/.config/sqlite3/sqliterc",home);
    if(access(cfg,R_OK)==0){ char *r=xstrdup(cfg); sqlite3_free(cfg); return r; }
    sqlite3_free(cfg);
  }
  { char *rc=sqlite3_mprintf("%s/.sqliterc",home); if(access(rc,R_OK)==0){ char *r=xstrdup(rc); sqlite3_free(rc); return r; } sqlite3_free(rc); }
  return 0;
}
static void print_version_line(void){
  printf("%s %s (%s-bit)\n",SHELL_SQLITE_VERSION,SHELL_SOURCE_ID,sizeof(void*)==8?"64":"32");
}
int main(int argc, char **argv){
  Shell sh; Shell *p=&sh;
  int i;
  const char *zDbArg=0;
  char *zInitFile=0; int noInit=0;
  char **sqlArgs=0; int *sqlArgIdx=0; int nSql=0,capSql=0;
  int seenDb=0, disableOpts=0;
  int optInteractive=0,optBatch=0;
  int terminalAction=0; /* 1 help 2 version */
  int archiveMode=0; int archiveStartArg=0;
  int lookSz=0,lookN=0,pageSz=0,pageN=0;
  sqlite3_int64 mmapSize=-1;
  int memtrace=0,pcachetrace=0,vfstrace=0;
  int startupHadError=0;
  memset(&sh,0,sizeof(sh));
  gShell=p;
  p->out=stdout;
  modeset_preset(&p->mode,MODE_List);
  p->zPrompt=xstrdup(getenv("SQLITE_PS1")?getenv("SQLITE_PS1"):"SQLite /f> ");
  p->zContinuePrompt=xstrdup(getenv("SQLITE_PS2")?getenv("SQLITE_PS2"):"/B.../H> ");
  p->eExplain=2;
  p->limitParserDepth=2500;
  p->cfgAttachCreate=1;p->cfgAttachWrite=1;p->cfgComments=1;p->cfgFpDigits=17;
  p->stdinIsTty=isatty(STDIN_FILENO);
  p->stdoutIsTty=isatty(STDOUT_FILENO);
  signal(SIGINT,sigint_handler);
  /* ---- parse arguments ---- */
  for(i=1;i<argc;i++){
    char *z=argv[i];
    if(archiveMode) break;
    if(!disableOpts && z[0]=='-' && z[1]!=0){
      const char *opt=z+1;
      if(!strcmp(z,"--")){ disableOpts=1; continue; }
      if(opt[0]=='-') opt++;
      if(!strcmp(opt,"A")){ archiveMode=1; archiveStartArg=i+1; break; }
      else if(!strcmp(opt,"help")){ terminalAction=1; break; }
      else if(!strcmp(opt,"version")){ terminalAction=2; break; }
      else if(!strcmp(opt,"append")) p->appendFlag=1;
      else if(!strcmp(opt,"zip")) p->zipFlag=1;
      else if(!strcmp(opt,"deserialize")) p->deserializeFlag=1;
      else if(!strcmp(opt,"readonly")) p->readOnlyFlag=1;
      else if(!strcmp(opt,"ifexists")) p->ifExistsFlag=1;
      else if(!strcmp(opt,"nofollow")) p->noFollow=1;
      else if(!strcmp(opt,"noinit")) noInit=1;
