        if(i+1>=argc){ fprintf(stderr,"%s: Error: missing argument to -%s\n",argv[0],opt); return 1; }
        { char *val=argv[++i];
          if(!strcmp(opt,"cmd")) add_action(1,0,val,i);
          else if(!strcmp(opt,"init")){ free(zInitFile); zInitFile=xstrdup(val); }
          else if(!strcmp(opt,"separator")) add_action(7,0,val,i);
          else if(!strcmp(opt,"newline")) add_action(8,0,val,i);
          else if(!strcmp(opt,"nullvalue")) add_action(9,0,val,i);
          else if(!strcmp(opt,"vfs")){ free(p->zVfs); p->zVfs=xstrdup(val); }
          else if(!strcmp(opt,"mmap")) mmapSize=atoll(val);
          else if(!strcmp(opt,"screenwidth")){
            int v=atoi(val);
            if(v<2){ fprintf(stderr,"minimum --screenwidth is 2\n"); return 1; }
            add_action(11,v,0,i);
          }
          else if(!strcmp(opt,"nonce")){ free(p->zNonce); p->zNonce=xstrdup(val); }
        }
      }
      else if(!strcmp(opt,"lookaside")||!strcmp(opt,"pagecache")){
        if(i+1>=argc){ fprintf(stderr,"%s: Error: missing argument to -%s\n",argv[0],opt); return 1; }
        { char *v1=argv[++i];
          if(i+1>=argc){ fprintf(stderr,"%s: Error: missing argument to %s\n",argv[0],v1); return 1; }
          { char *v2=argv[++i];
            if(!strcmp(opt,"lookaside")){ lookSz=atoi(v1); lookN=atoi(v2); }
            else { pageSz=atoi(v1); pageN=atoi(v2); }
          }
        }
      }
      else if(!strcmp(opt,"maxsize")&&i+1<argc){ p->maxSize=atoll(argv[++i]); }
      else if(!strcmp(opt,"escape")&&i+1<argc){
        char *val=argv[++i]; int esc;
        if(!strcmp(val,"symbol"))esc=ESC_Symbol; else if(!strcmp(val,"ascii"))esc=ESC_Ascii; else if(!strcmp(val,"off"))esc=ESC_Off; else if(!strcmp(val,"auto"))esc=ESC_Auto;
        else { fprintf(stderr,"unknown control character escape mode \"%s\" - choices: auto off ascii symbol\n",val); return 1; }
        add_action(10,esc,0,i);
      }
      else {
