    }
    if(!seenDb){ zDbArg=z; seenDb=1; }
    else {
      if(nSql>=capSql){capSql=capSql?capSql*2:16;sqlArgs=(char**)xrealloc(sqlArgs,sizeof(char*)*capSql);sqlArgIdx=(int*)xrealloc(sqlArgIdx,sizeof(int)*capSql);}
