  if typ=='null':serials.append(0)
  elif typ=='int':
    if v==0:serials.append(8)
    elif v==1:serials.append(9)
    elif -128<=v<128:serials.append(1);payload+=struct.pack('>b',v)
    elif -32768<=v<32768:serials.append(2);payload+=struct.pack('>h',v)
    elif -2**23<=v<2**23:serials.append(3);payload+=v.to_bytes(3,'big',signed=True)
    elif -2**31<=v<2**31:serials.append(4);payload+=struct.pack('>i',v)
    elif -2**47<=v<2**47:serials.append(5);payload+=v.to_bytes(6,'big',signed=True)
    else:serials.append(6);payload+=struct.pack('>q',v)
  elif typ=='float':serials.append(7);payload+=struct.pack('>d',v)
  elif typ=='text':b=v.encode();serials.append(13+2*len(b));payload+=b
  elif typ=='blob':serials.append(12+2*len(v));payload+=v
 hdr=b''.join(varint(s) for s in serials)
 hl=len(hdr)+1
 # if varint length >1 iterative (not here)
 return varint(hl)+hdr+payload
