 'int1':('int',1),'int0':('int',0),'int-1':('int',-1),'int123':('int',123),'float1':('float',1.0),
 'texta':('text','a'),'textempty':('text',''),'null':('null',None),'blob00':('blob',b'\x00'),'blobab':('blob',b'ab'),'text1':('text','1')}
# candidate transforms
candidates={}
def add(name,fn): candidates[name]=fn
