add('quote',lambda tv: { 'int':str(tv[1]),'float':'1.0','text':"'"+tv[1]+"'",'null':'NULL','blob':"x'"+tv[1].hex()+"'"}[tv[0]].encode())
# type byte sqlite type code (1 int,2 float,3 text,4 blob,5 null) + payload text/blob/int be/float be
def typepayload(tv, endian='>'):
 typ,v=tv; codes={'int':1,'float':2,'text':3,'blob':4,'null':5}
