add('type+le',lambda tv:typepayload(tv,'<'))
add('type+text',lambda tv:bytes([{'int':1,'float':2,'text':3,'blob':4,'null':5}[tv[0]]])+({'int':str(tv[1]),'float':'1.0','text':tv[1],'null':''}[tv[0]].encode() if tv[0]!='blob' else tv[1]))
# length prefixed text etc
for name,fn in candidates.items():
