import hashlib,json,itertools
cases=json.load(open('/tmp/sha_cases.json'))
def H(b):return hashlib.sha3_256(b).hexdigest().upper()
vals={'int1':('int',1),'int0':('int',0),'int-1':('int',-1),'int123':('int',123),'float1':('float',1.0),'texta':('text','a'),'textempty':('text',''),'null':('null',None),'blob00':('blob',b'\x00'),'blobab':('blob',b'ab'),'text1':('text','1')}
type_names={
 'lower':{'int':'integer','float':'real','text':'text','blob':'blob','null':'null'},
 'upper':{'int':'INTEGER','float':'REAL','text':'TEXT','blob':'BLOB','null':'NULL'},
 'short':{'int':'int','float':'float','text':'text','blob':'blob','null':'null'},
 'letter':{'int':'i','float':'f','text':'t','blob':'b','null':'n'},
 'sqltype':{'int':'1','float':'2','text':'3','blob':'4','null':'5'},
}
def vrep(tv,style):
 typ,v=tv
 if style=='rawtext':
  return {'int':str(v),'float':'1.0','text':v,'null':''}[typ].encode() if typ!='blob' else v
 if style=='quote':
  if typ=='int':return str(v).encode()
  if typ=='float':return b'1.0'
  if typ=='text':return ("'"+v+"'").encode()
  if typ=='null':return b'NULL'
  return ("x'"+v.hex()+"'").encode()
 if style=='hexblob':
  return {'int':str(v),'float':'1.0','text':v,'null':'NULL'}[typ].encode() if typ!='blob' else v.hex().encode()
 if style=='reprnull':
  return {'int':str(v),'float':'1.0','text':v,'null':'NULL'}[typ].encode() if typ!='blob' else v
templates=[
 lambda T,V,L: T+V,
 lambda T,V,L: T+b':'+V,
 lambda T,V,L: T+b'='+V,
 lambda T,V,L: T+b' '+V,
 lambda T,V,L: T+b'('+V+b')',
 lambda T,V,L: V+b'('+T+b')',
 lambda T,V,L: L+b':'+T+b':'+V,
 lambda T,V,L: T+b':'+L+b':'+V,
 lambda T,V,L: L+T+V,
 lambda T,V,L: T+L+V,
 lambda T,V,L: V,
 lambda T,V,L: L+b':'+V,
]
found=False
for tname,tdict in type_names.items():
 for vstyle in ['rawtext','quote','hexblob','reprnull']:
  for ti,tmpl in enumerate(templates):
   for sep in [b'',b'\n',b'\x00',b'|',b',',b';',b'\x1e',b'\x1f',b' ']:
    ok=True
    for cn,tv in vals.items():
     V=vrep(tv,vstyle); T=tdict[tv[0]].encode(); L=str(len(V)).encode()
     if H(tmpl(T,V,L)+sep)!=cases[cn]:ok=False;break
    if ok:print('FOUND',tname,vstyle,ti,sep);found=True
print('found',found)
