 ("select 1",[["1"]]),("select 1 as a",[["1"]]),("select 1 as b",[["1"]]),("select 2",[["2"]]),
 ("select 1,2",[["1","2"]]),("select 1 as a, 2 as b",[["1","2"]]),
 ("select 'a' as x",[["a"]]),("select null",[[None]]),("select 1 union all select 2",[["1"],["2"]]),("select 1 where 0",[]),
]
targets=[q(sql) for sql,_ in queries]
