def H(b):return hashlib.sha3_256(b).hexdigest().upper()
seps=['','\n','|','\x00',' ',';','\x1f',','\t']
colseps=['','|',',',' ','\t','\x1f',':']
rowseps=['','\n','\r\n','\x1e','|',',',';','\x00',' ']
nulls=['','NULL','null','(null)']
for sqlsep in seps:
 for cs in colseps:
  for rs in rowseps:
   for nullrep in nulls:
    for trail in [False,True]:
     ok=True
     for (sql,rows),t in zip(queries,targets):
      doc=sql+sqlsep+rs.join(cs.join(nullrep if v is None else v for v in row) for row in rows)+ (rs if trail and rows else '')
      if H(doc.encode())!=t:ok=False;break
     if ok:print('FOUND',repr(sqlsep),repr(cs),repr(rs),nullrep,trail)
print('done')
