import subprocess,hashlib
def q(sql):
 qq="select hex(sha3_query('"+sql.replace("'","''")+"'));"
 p=subprocess.run(["./executable",":memory:",qq],text=True,capture_output=True);return p.stdout.strip()
# each row cell (name,type,text)
queries=[
 ("select 1", [[("1",'int',"1")]]),
 ("select 1 as a", [[("a",'int',"1")]]),
 ("select 1 as b", [[("b",'int',"1")]]),
 ("select 1,2", [[("1",'int',"1"),("2",'int',"2")]]),
 ("select 'a' as x", [[("x",'text',"a")]]),
 ("select '1' as x", [[("x",'text',"1")]]),
 ("select 1.0 as x", [[("x",'float',"1.0")]]),
 ("select null as x", [[("x",'null',None)]]),
 ("select 1 where 0", []),
 ("select 1 union all select 2", [[("1",'int',"1")],[("1",'int',"2")]]),
]
targets=[]
for sql,_ in queries:
 t=q(sql);targets.append(t);print(sql,t)
def H(b):return hashlib.sha3_256(b.encode() if isinstance(b,str) else b).hexdigest().upper()
typechars=[
 {'int':'','float':'','text':'','null':''},
 {'int':'i','float':'f','text':'t','null':'n'},
 {'int':'1','float':'2','text':'3','null':'5'},
 {'int':'integer','float':'real','text':'text','null':'null'},
 {'int':'INTEGER','float':'REAL','text':'TEXT','null':'NULL'},
]
seps=['','\n',chr(0),'|',',',' ']
namevals=['',':','=',' ']
nulls=['','NULL','null','(null)']
orders=[0,1,2,3]
for tc in typechars:
 for sep in seps:
  for nv in namevals:
   for nullrep in nulls:
    for order in orders:
     ok=True
     for (sql,rows),t in zip(queries,targets):
      toks=[]
      if order in (0,1):toks.append(sql)
      for row in rows:
       for name,typ,val in row:
        v=nullrep if val is None else val
        if order==0: # sql, then per cell name nv type+val as one token
         toks.append(name+nv+tc[typ]+v)
        elif order==1: # sql, names token(s) then vals per row: approximate by names in first row only handled below
         toks.append(tc[typ]+v)
        elif order==2:
         toks.append(name+nv+tc[typ]+v)
        else:
         toks.append(tc[typ]+v)
      if order==1 and rows:
       # insert names after sql
       toks=[sql]+[name for name,typ,val in rows[0]]+toks[1:]
      if order in (2,3):toks.append(sql)
      if H(sep.join(toks))!=t:ok=False;break
     if ok:print('FOUND',tc,repr(sep),repr(nv),nullrep,order)
print('done')
