typedef struct SeriesCursor SeriesCursor;
struct SeriesCursor { sqlite3_vtab_cursor base; sqlite3_int64 iCur; sqlite3_int64 iStart; sqlite3_int64 iStop; sqlite3_int64 iStep; };
static int series_connect(sqlite3 *db,void *aux,int argc,const char *const*argv,sqlite3_vtab **ppVtab,char **pzErr){
  SeriesVtab *v=(SeriesVtab*)sqlite3_malloc(sizeof(SeriesVtab)); (void)aux;(void)argc;(void)argv;(void)pzErr;
  if(!v)return SQLITE_NOMEM; memset(v,0,sizeof(*v));
  if(sqlite3_declare_vtab(db,"CREATE TABLE x(value,start HIDDEN,stop HIDDEN,step HIDDEN)")!=SQLITE_OK){ sqlite3_free(v); return SQLITE_ERROR; }
  *ppVtab=&v->base; return SQLITE_OK;
}
static int series_disconnect(sqlite3_vtab *pVtab){ sqlite3_free(pVtab); return SQLITE_OK; }
static int series_open(sqlite3_vtab *pVtab,sqlite3_vtab_cursor **ppCursor){
  SeriesCursor *c=(SeriesCursor*)sqlite3_malloc(sizeof(SeriesCursor)); (void)pVtab;
  if(!c)return SQLITE_NOMEM; memset(c,0,sizeof(*c)); *ppCursor=&c->base; return SQLITE_OK;
}
static int series_close(sqlite3_vtab_cursor *cur){ sqlite3_free(cur); return SQLITE_OK; }
static int series_eof(sqlite3_vtab_cursor *cur){
  SeriesCursor *c=(SeriesCursor*)cur;
  return c->iStep>0 ? (c->iCur>c->iStop) : (c->iCur<c->iStop);
}
static int series_next(sqlite3_vtab_cursor *cur){
  SeriesCursor *c=(SeriesCursor*)cur;
  c->iCur += c->iStep;
  return SQLITE_OK;
}
static int series_filter(sqlite3_vtab_cursor *cur,int idxNum,const char *idxStr,int argc,sqlite3_value **argv){
  SeriesCursor *c=(SeriesCursor*)cur; int i;
  sqlite3_int64 iMin=0,iMax=4294967295LL,iStep=1;
  (void)idxNum;
  for(i=0;i<argc;i++){
    char code=idxStr?idxStr[i]:0; sqlite3_int64 v=sqlite3_value_int64(argv[i]);
    switch(code){
      case 's': iMin=v; break;
      case 'e': iMax=v; break;
      case 'p': iStep=v; break;
      case '=': iMin=v; iMax=v; break;
      case 'g': if(v+1>iMin)iMin=v+1; break; /* value > v, only meaningful ascending assembled below */
      case 'G': if(v>iMin)iMin=v; break;
      case 'l': if(v-1<iMax)iMax=v-1; break;
      case 'L': if(v<iMax)iMax=v; break;
    }
  }
  if(iStep==0)iStep=1;
  c->iStep=iStep;
  if(iStep>0){ c->iStart=iMin; c->iStop=iMax; }
  else { c->iStart=iMax; c->iStop=iMin; }
  /* If explicit start/stop were given for negative step, the generic min/max handling above loses direction.
  ** Re-apply directional start/stop for 's'/'e' args: for negative step, start should be the s value and stop e value. */
  if(iStep<0){
    for(i=0;i<argc;i++){
      char code=idxStr?idxStr[i]:0; sqlite3_int64 v=sqlite3_value_int64(argv[i]);
      if(code=='s')c->iStart=v;
      if(code=='e')c->iStop=v;
      if(code=='='){c->iStart=v;c->iStop=v;}
    }
  }else{
    for(i=0;i<argc;i++){
      char code=idxStr?idxStr[i]:0; sqlite3_int64 v=sqlite3_value_int64(argv[i]);
      if(code=='s')c->iStart=v;
      if(code=='e')c->iStop=v;
      if(code=='='){c->iStart=v;c->iStop=v;}
      if(code=='g' && c->iStart<v+1)c->iStart=v+1;
      if(code=='G' && c->iStart<v)c->iStart=v;
      if(code=='l' && c->iStop>v-1)c->iStop=v-1;
      if(code=='L' && c->iStop>v)c->iStop=v;
    }
  }
  c->iCur=c->iStart;
  return SQLITE_OK;
}
static int series_column(sqlite3_vtab_cursor *cur,sqlite3_context *ctx,int col){
