  memmove(&arr->a[idx+1],&arr->a[idx],sizeof(JVal*)*(arr->cnt-idx));
  if(arr->ak)memmove(&arr->ak[idx+1],&arr->ak[idx],sizeof(char*)*(arr->cnt-idx));
  if(arr->akn)memmove(&arr->akn[idx+1],&arr->akn[idx],sizeof(size_t)*(arr->cnt-idx));
  if(arr->akRaw)memmove(&arr->akRaw[idx+1],&arr->akRaw[idx],sizeof(char*)*(arr->cnt-idx));
