  if(arr->akEsc)memmove(&arr->akEsc[idx+1],&arr->akEsc[idx],sizeof(int)*(arr->cnt-idx));
  arr->a[idx]=item; if(arr->ak)arr->ak[idx]=0; if(arr->akn)arr->akn[idx]=0; if(arr->akRaw)arr->akRaw[idx]=0; if(arr->akRawN)arr->akRawN[idx]=0; if(arr->akEsc)arr->akEsc[idx]=0;
  arr->cnt++;
