import hashlib,struct
def H(b):return hashlib.sha3_256(b).hexdigest().upper()
def E(tv):
 t,v=tv
 if t=='null':return b'N'
 if t=='int':return b'I'+struct.pack('>q',v)
 if t=='text':b=v.encode();return b'T'+str(len(b)).encode()+b':'+b
sql="select 1 where 0"; target='254157733246A5DAEC6B628A8B387635E0AF2137FCC9D919D821D0B509A709F9'
for sqlatom_name,sqlatom in [('E',E(('text',sql))),('raw',sql.encode())]:
 for nameatom_name,nameatom in [('Ename',E(('text','1'))),('rawname',b'1'),('none',b'')]:
  base1=sqlatom+nameatom; base2=nameatom+sqlatom
  for bi,base in enumerate([base1,base2]):
   if H(base)==target:print('exact',sqlatom_name,nameatom_name,bi)
   for pre in range(256):
    if H(bytes([pre])+base)==target:print('pre',sqlatom_name,nameatom_name,bi,pre)
    if H(base+bytes([pre]))==target:print('suf',sqlatom_name,nameatom_name,bi,pre)
   # one byte between sql and name
   if bi==0:
    for mid in range(256):
     if H(sqlatom+bytes([mid])+nameatom)==target:print('mid',sqlatom_name,nameatom_name,mid)
print('done')
