static int match_paren_fwd(const char *z,STok *a,int n,int openIdx){
  int depth=0; int i;
  for(i=openIdx;i<n;i++){
    if(tok_is(z,&a[i],"("))depth++;
    else if(tok_is(z,&a[i],")")){depth--; if(depth==0)return i;}
  }
  return -1;
}
static int match_paren_bwd(const char *z,STok *a,int n,int closeIdx){
  int depth=0; int i; (void)n;
  for(i=closeIdx;i>=0;i--){
    if(tok_is(z,&a[i],")"))depth++;
    else if(tok_is(z,&a[i],"(")){depth--; if(depth==0)return i;}
  }
