  int i; for(i=0;kws[i];i++) if(tok_eq(z,t,kws[i]))return 1;
  return 0;
}
/* Returns token index range [start,end] (inclusive) for a primary ending at token k, or -1 */
static int primary_left_start(const char *z,STok *a,int n,int k){
  (void)n;
  if(k<0)return -1;
  if(tok_is(z,&a[k],")")){
    int open=match_paren_bwd(z,a,n,k);
    if(open<0)return -1;
    if(open>0&&a[open-1].type==0&&!is_nonfunc_keyword(z,&a[open-1])) return open-1;
    return open;
  }
  if(a[k].type==0||a[k].type==1||a[k].type==2||a[k].type==3||a[k].type==5){
    int start=k;
    while(start>=2&&tok_is(z,&a[start-1],".")&&(a[start-2].type==0||a[start-2].type==3)) start-=2;
    return start;
  }
  return -1;
}
static int primary_right_end(const char *z,STok *a,int n,int k){
  if(k>=n)return -1;
  if(tok_is(z,&a[k],"(")){
    return match_paren_fwd(z,a,n,k);
  }
  if(tok_is(z,&a[k],"-")||tok_is(z,&a[k],"+")){
    if(k+1<n&&a[k+1].type==1) return k+1;
    return -1;
  }
  if(a[k].type==0||a[k].type==1||a[k].type==2||a[k].type==3||a[k].type==5){
    int end=k;
    if(end+1<n&&tok_is(z,&a[end+1],"(")){
      int m=match_paren_fwd(z,a,n,end+1); if(m<0)return -1; end=m;
    }
    while(end+2<n&&tok_is(z,&a[end+1],".")&&(a[end+2].type==0||a[end+2].type==3)) end+=2;
    return end;
  }
  return -1;
}
static char *transform_json_arrows(const char *zIn){
  char *cur=xstrdup(zIn); int iter;
  for(iter=0;iter<100;iter++){
    int n=0; STok *a=sql_tokenize(cur,&n); int i; int arrow=-1; int isDouble=0;
    for(i=0;i<n;i++){
      if(tok_is(cur,&a[i],"->>")){arrow=i;isDouble=1;break;}
      if(tok_is(cur,&a[i],"->")){arrow=i;isDouble=0;break;}
    }
    if(arrow<0){free(a);break;}
    {
      int ls=primary_left_start(cur,a,n,arrow-1);
      int re=primary_right_end(cur,a,n,arrow+1);
      Str out;
      if(ls<0||re<0){free(a);break;}
      str_init(&out);
      str_append_n(&out,cur,a[ls].start);
      str_append(&out,isDouble?"json_extract(":"__shell_json_arrow(");
      str_append_n(&out,cur+a[ls].start,a[arrow].start-a[ls].start);
      /* trim trailing spaces of left operand */
      while(out.n&&isspace((unsigned char)out.s[out.n-1]))out.n--;
      str_append_c(&out,',');
      str_append_n(&out,cur+a[arrow+1].start,a[re].end-a[arrow+1].start);
      str_append_c(&out,')');
      str_append(&out,cur+a[re].end);
      free(a); free(cur); cur=str_detach(&out);
    }
  }
  if(cur&&strcmp(cur,zIn)==0){free(cur);return 0;}
  return cur;
}
