static int tok_depth_at(const char *z,STok *a,int idx){
  int d=0; int i;
  for(i=0;i<idx;i++){ if(tok_is(z,&a[i],"("))d++; else if(tok_is(z,&a[i],")"))d--; }
  return d;
}
static int parse_table_primary(const char *z,STok *a,int n,int pos,int *pend,char **pzAlias,char **pzTable){
  int i=pos;
  if(pzAlias)*pzAlias=0; if(pzTable)*pzTable=0;
  if(i>=n)return 0;
  if(tok_is(z,&a[i],"(")){
    int m=match_paren_fwd(z,a,n,i);
    if(m<0)return 0;
    i=m+1;
  }else if(a[i].type==0||a[i].type==3){
    if(pzTable)*pzTable=xstrndup(z+a[i].start,a[i].end-a[i].start);
    i++;
