    i++;
  }
  if(i<n&&tok_eq(z,&a[i],"indexed")&&i+2<n&&tok_eq(z,&a[i+1],"by")) i+=3;
  else if(i+1<n&&tok_eq(z,&a[i],"not")&&tok_eq(z,&a[i+1],"indexed")) i+=2;
  *pend=i;
  return 1;
}
static char **get_table_columns(Shell *p,const char *zTable,int *pn){
  /* zTable may be quoted; strip quotes */
  char *name=xstrdup(zTable); size_t L=strlen(name);
  RowSet rs; char *e=0; char *q; char **az=0; int n2=0; int i;
  *pn=0;
  if(L>=2&&((name[0]=='"'&&name[L-1]=='"')||(name[0]=='`'&&name[L-1]=='`')||(name[0]=='['&&name[L-1]==']'))){ name[L-1]=0; memmove(name,name+1,L-1); }
  q=sqlite3_mprintf("PRAGMA table_info(\"%w\");",name);
