}
static char *transform_right_join(Shell *p,const char *zIn){
  char *cur=xstrdup(zIn); int iter;
  for(iter=0;iter<20;iter++){
    int n=0; STok *a=sql_tokenize(cur,&n); int i; int rj=-1; int joinTok=-1;
