            str_append_n(&out,cur,a[starTok].start);
            for(k=0;k<na;k++){ char *qc=quote_identifier(ca[k]); if(!first)str_append_c(&out,','); str_appendf(&out,"%s.%s",alA,qc); free(qc); first=0; }
            for(k=0;k<nb;k++){ char *qc=quote_identifier(cb[k]); if(!first)str_append_c(&out,','); str_appendf(&out,"%s.%s",alB,qc); free(qc); first=0; }
            str_append_n(&out,cur+a[starTok].end,a[aStart].start-a[starTok].end);
          }else{
            str_append_n(&out,cur,a[aStart].start);
          }
          for(i=0;i<na;i++)free(ca[i]); free(ca);
          for(i=0;i<nb;i++)free(cb[i]); free(cb);
        }else{
          str_append_n(&out,cur,a[aStart].start);
        }
