              if(strcasecmp(col,"rowid")&&strcasecmp(col,"_rowid_")&&strcasecmp(col,"oid")){
                if(isEq) exp_add_cand(&tabs[t2],col);
                else {
                  /* range candidates appended after eq candidates: approximate by adding now (order may differ in mixed cases) */
                  exp_add_cand(&tabs[t2],col);
                }
              }
              ti=t2; break;
            }
          }
          (void)ti;
        }
        free(col); free(qual);
      }
      (void)isRange;
    }
    /* ORDER BY / GROUP BY column references */
    for(k=0;k+1<n;k++){
      if(a[k].type==0&&(tok_eq(zSql,&a[k],"order")||tok_eq(zSql,&a[k],"group"))&&tok_eq(zSql,&a[k+1],"by")){
        int j;
        for(j=k+2;j<n;j++){
          if(tok_depth_at(zSql,a,j)==0&&a[j].type==0&&(tok_eq(zSql,&a[j],"limit")||tok_eq(zSql,&a[j],"having")||tok_eq(zSql,&a[j],"union")))break;
          if(a[j].type==0||a[j].type==3){
            char *col=xstrndup(zSql+a[j].start,a[j].end-a[j].start); int t2;
            /* qualified? */
            const char *qual=0; char *qualBuf=0;
            if(j+2<n&&tok_is(zSql,&a[j+1],".")){ qualBuf=col; qual=qualBuf; col=xstrndup(zSql+a[j+2].start,a[j+2].end-a[j+2].start); j+=2; }
            for(t2=0;t2<nTab;t2++){
              if(qual&&strcasecmp(qual,tabs[t2].zAlias)!=0&&strcasecmp(qual,tabs[t2].zName)!=0)continue;
              if(exp_table_has_col(&tabs[t2],col)&&strcasecmp(col,"rowid")) exp_add_cand(&tabs[t2],col);
            }
            free(col); free(qualBuf);
          }
        }
      }
    }
  }
  /* 3) Decide suggestions */
  {
    int ti;
    for(ti=0;ti<nTab;ti++){
      ExpTable *t=&tabs[ti]; int covered=0; Str joined; char *idxName; int ci;
      if(t->nCand==0)continue;
      /* IPK single column check */
      {
        char *q=sqlite3_mprintf("PRAGMA table_info(\"%w\");",t->zName); RowSet rs; char *e=0; int pkCols=0; const char *pkCol=0; int pkIsInt=0;
        if(query_collect(p,q,&rs,&e)==SQLITE_DONE){
          int r2; for(r2=0;r2<rs.nRow;r2++) if(atoi(rs.aaRaw[r2][5])>0){pkCols++;pkCol=rs.aaRaw[r2][1];pkIsInt=!strcasecmp(rs.aaRaw[r2][2],"INTEGER");}
          if(pkCols==1&&t->nCand>=1&&pkCol&&!strcasecmp(pkCol,t->azCand[0])) covered=1;
          (void)pkIsInt;
        }
        rowset_free(&rs); free(e); sqlite3_free(q);
      }
      if(!covered){
        char *q=sqlite3_mprintf("PRAGMA index_list(\"%w\");",t->zName); RowSet rs; char *e=0; int r2;
        if(query_collect(p,q,&rs,&e)==SQLITE_DONE){
          for(r2=0;r2<rs.nRow&&!covered;r2++){
            char *q2=sqlite3_mprintf("PRAGMA index_info(\"%w\");",rs.aaRaw[r2][1]); RowSet xi; int ok2=1; int c2;
            if(query_collect(p,q2,&xi,&e)==SQLITE_DONE){
              if(xi.nRow<t->nCand)ok2=0;
              for(c2=0;ok2&&c2<t->nCand;c2++) if(strcasecmp(xi.aaRaw[c2][2],t->azCand[c2])!=0)ok2=0;
              if(ok2)covered=1;
            }
            rowset_free(&xi); sqlite3_free(q2);
          }
        }
        rowset_free(&rs); free(e); sqlite3_free(q);
      }
      if(covered)continue;
      str_init(&joined);
      for(ci=0;ci<t->nCand;ci++){ if(ci)str_append(&joined,", "); str_append(&joined,t->azCand[ci]); }
      idxName=sqlite3_mprintf("%s_idx_%08x",t->zName,exp_name_hash(joined.s?joined.s:""));
      {
        char *stmt=sqlite3_mprintf("CREATE INDEX %s ON %s(%s);",idxName,t->zName,joined.s?joined.s:"");
        if(nSugg>=capSugg){capSugg=capSugg?capSugg*2:8;azSugg=(char**)xrealloc(azSugg,sizeof(char*)*capSugg);}
        azSugg[nSugg++]=xstrdup(stmt);
        sqlite3_free(stmt);
      }
      sqlite3_free(idxName);
      str_free(&joined);
    }
  }
  /* 4) Print suggestions, create them in a savepoint, run EQP, rollback */
  {
    int si;
    if(nSugg==0) out_write(p,"(no new indexes)\n\n");
    else for(si=0;si<nSugg;si++) out_printf(p,"%s\n",azSugg[si]);
    if(nSugg>0) out_write(p,"\n");
    exec_simple(p,"SAVEPOINT _shell_expert;",0);
    for(si=0;si<nSugg;si++) exec_simple(p,azSugg[si],0);
    {
      char *zQ=sqlite3_mprintf("EXPLAIN QUERY PLAN %s",zSql); RowSet rs; char *e=0; int rc2;
      rc2=query_collect(p,zQ,&rs,&e); sqlite3_free(zQ);
      if(rc2==SQLITE_DONE||rc2==SQLITE_OK){
        for(si=0;si<rs.nRow;si++){ if(rs.nCol>=4)out_write(p,rs.aaRaw[si][3]); out_write(p,"\n"); }
      }else if(e){
        report_sql_error(p,1,zSql,e,ctx,startLine);
      }
      rowset_free(&rs); free(e);
    }
    exec_simple(p,"ROLLBACK TO _shell_expert; RELEASE _shell_expert;",0);
    out_write(p,"\n");
  }
  {
    int ti,si;
    for(ti=0;ti<nTab;ti++){ free(tabs[ti].zName);free(tabs[ti].zAlias); {int j;for(j=0;j<tabs[ti].nCol;j++)free(tabs[ti].azCols[j]);free(tabs[ti].azCols);} {int j;for(j=0;j<tabs[ti].nCand;j++)free(tabs[ti].azCand[j]);free(tabs[ti].azCand);} }
    free(tabs);
    for(si=0;si<nSugg;si++)free(azSugg[si]); free(azSugg);
  }
  free(a);
  return 0;
}
EOF
echo ok"}

